(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.apiao||(w.apiao={});a[2]={"work":"apiao","book":2,"title":"Φλαΐου Ἰωσήπου περὶ ἀρχαιότητος ἀντιρρητικὸς λόγος β.","chapters":{"1":[{"number":1,"text":"Διὰ μὲν οὖν τοῦ προτέρου βιβλίου, τιμιώτατέ μοι Ἐπαφρόδιτε, περί τε τῆς ἀρχαιότητος ἡμῶν ἐπέδειξα τοῖς Φοινίκων καὶ Χαλδαίων καὶ Αἰγυπτίων γράμμασι πιστωσάμενος τὴν ἀλήθειαν καὶ πολλοὺς τῶν Ἑλλήνων συγγραφεῖς παρασχόμενος μάρτυρας, τήν τε ἀντίρρησιν ἐποιησάμην πρὸς Μανεθὼν καὶ Χαιρήμονα καί τινας ἑτέρους."},{"number":2,"text":"ἄρξομαι δὲ νῦν τοὺς ὑπολειπομένους τῶν γεγραφότων τι καθʼ ἡμῶν ἐλέγχειν καὶ τοῖς τῆς πρὸς Ἀπίωνα τὸν γραμματικὸν ἀντιρρήσεως τετολμημένοις ἐπῆλθέ μοι διαπορεῖν, εἰ χρὴ σπουδάσαι·"},{"number":3,"text":"τὰ μὲν γάρ ἐστι τῶν ὑπʼ αὐτοῦ γεγραμμένων τοῖς ὑπʼ ἄλλων εἰρημένοις ὅμοια, τὰ δὲ λίαν ψυχρῶς προστέθεικεν, τὰ πλεῖστα δὲ βωμολοχίαν ἔχει καὶ πολλήν, εἰ δεῖ τἀληθὲς εἰπεῖν, ἀπαιδευσίαν ὡς ἂν ὑπʼ ἀνθρώπου συγκείμενα καὶ φαύλου τὸν τρόπον καὶ παρὰ πάντα τὸν βίον ὀχλαγωγοῦ γεγονότος."},{"number":4,"text":"ἐπεὶ δʼ οἱ πολλοὶ τῶν ἀνθρώπων διὰ τὴν αὐτῶν ἄνοιαν ὑπὸ τῶν τοιούτων ἁλίσκονται λόγων μᾶλλον ἢ τῶν μετά τινος σπουδῆς γεγραμμένων, καὶ χαίρουσι μὲν ταῖς λοιδορίαις, ἄχθονται δὲ τοῖς ἐπαίνοις, ἀναγκαῖον ἡγησάμην εἶναι μηδὲ τοῦτον ἀνεξέταστον καταλιπεῖν κατηγορίαν ἡμῶν ἄντικρυς ὡς ἐν δίκῃ γεγραφότα."},{"number":5,"text":"καὶ γὰρ αὖ κἀκεῖνο τοῖς πολλοῖς ἀνθρώποις ὁρῶ παρακολουθοῦν, τὸ λίαν ἐφήδεσθαι ὅταν τις ἀρξάμενος βλασφημεῖν ἕτερον αὐτὸς ἐλέγχηται περὶ τῶν αὐτῷ προσόντων κακῶν."},{"number":6,"text":"ἔστι μὲν οὖν οὐ ῥᾴδιον αὐτοῦ διελθεῖν τὸν λόγον οὐδὲ σαφῶς γνῶναι, τί λέγειν βούλεται, σχεδὸν δʼ ὡς ἐν πολλῇ ταραχῇ καὶ ψευσμάτων συγχύσει τὰ μὲν εἰς τὴν ὁμοίαν ἰδέαν πίπτει τοῖς προεξητασμένοις περὶ τῆς ἐξ Αἰγύπτου τῶν ἡμετέρων προγόνων μεταναστάσεως,"},{"number":7,"text":"τὰ δʼ ἐστὶ κατηγορία τῶν ἐν Ἀλεξανδρείᾳ κατοικούντων Ἰουδαίων. τρίτον δʼ ἐπὶ τούτοις μέμικται περὶ τῆς ἁγιστείας τῆς κατὰ τὸ ἱερὸν ἡμῶν καὶ τῶν ἄλλων νομίμων κατηγορία."},{"number":8,"text":"Ὅτι μὲν οὖν οὔτε Αἰγύπτιοι τὸ γένος ἦσαν ἡμῶν οἱ πατέρες οὔτε διὰ λύμην σωμάτων ἢ τοιαύτας ἄλλας συμφοράς τινας ἐκεῖθεν ἐξηλάθησαν, οὐ μετρίως μόνον, ἀλλὰ καὶ πέρα τοῦ συμμέτρου προαποδεδεῖχθαι νομίζω."},{"number":9,"text":"περὶ ὧν δὲ προστίθησιν ὁ Ἀπίων ἐπιμνησθήσομαι συντόμως."},{"number":10,"text":"φησὶ γὰρ ἐν τῇ τρίτῃ τῶν Αἰγυπτιακῶν τάδε· Μωσῆς, ὡς ἤκουσα παρὰ τῶν πρεσβυτέρων τῶν Αἰγυπτίων, ἦν Ἡλιοπολίτης, ὃς πατρίοις ἔθεσι κατηγγυημένος αἰθρίους προσευχὰς ἀνῆγεν εἰς οἵους εἶχεν ἥλιος περιβόλους, πρὸς ἀφηλιώτην δὲ πάσας ἀπέστρεφεν· ὧδε γὰρ καὶ Ἡλίου κεῖται πόλις."},{"number":11,"text":"ἀντὶ δὲ ὀβελῶν ἔστησε κίονας, ὑφʼ οἷς ἦν ἐκτύπωμα σκάφη, σκιὰ δʼ ἀνδρὸς ἐπʼ αὐτὴν διακειμένη, ὡς ὅτι ἐν αἰθέρι τοῦτον ἀεὶ τὸν δρόμον ἡλίῳ συμπεριπολεῖ."},{"number":12,"text":"τοιαύτη μέν τις ἡ θαυμαστὴ τοῦ γραμματικοῦ φράσις· τὸ δὲ ψεῦσμα λόγων οὐ δεόμενον, ἀλλʼ ἐκ τῶν ἔργων περιφανές· οὔτε γὰρ αὐτὸς Μωσῆς, ὅτε τὴν πρώτην σκηνὴν τῷ θεῷ κατεσκεύασεν, οὐθὲν ἐκτύπωμα τοιοῦτον εἰς αὐτὴν ἐνέθηκεν οὐδὲ ποιεῖν τοῖς ἔπειτα προσέταξεν, ὅ τε μετὰ ταῦτα κατασκευάσας τὸν ναὸν τὸν ἐν Ἱεροσολύμοις Σολομὼν πάσης ἀπέσχετο τοιαύτης περιεργίας οἵαν συμπέπλεκεν Ἀπίων."},{"number":13,"text":"ἀκοῦσαι δέ φησι τῶν πρεσβυτέρων, ὅτι Μωσῆς ἦν Ἡλιοπολίτης, δῆλον ὅτι νεώτερος μὲν ὢν αὐτός, ἐκείνοις δὲ πιστεύσας τοῖς διὰ τὴν ἡλικίαν ἐπισταμένοις αὐτὸν καὶ συγγενομένοις."},{"number":14,"text":"καὶ περὶ μὲν Ὁμήρου τοῦ ποιητοῦ γραμματικὸς ὢν αὐτὸς οὐκ ἂν ἔχοι, τίς αὐτοῦ πατρίς ἐστι, διαβεβαιωσάμενος εἰπεῖν οὐδὲ περὶ Πυθαγόρου μόνον οὐκ ἐχθὲς καὶ πρῴην γεγονότος, περὶ δὲ Μωσέως τοσούτῳ πλήθει προάγοντος ἐκείνους ἐτῶν οὕτως ἀποφαίνεται ῥᾳδίως πιστεύων ἀκοῇ πρεσβυτέρων, ὡς δῆλός ἐστι καταψευσάμενος."},{"number":15,"text":"τὰ δὲ δὴ τῶν χρόνων, ἐν οἷς φησι τὸν Μωσῆν ἐξαγαγεῖν τοὺς λεπρῶντας καὶ τυφλοὺς καὶ τὰς βάσεις πεπηρωμένους, σφόδρα δὴ τοῖς πρὸ αὐτοῦ συμπεφώνηκεν, ὡς οἶμαι, ὁ γραμματικὸς ὁ ἀκριβής."},{"number":16,"text":"Μανεθὼς μὲν γὰρ κατὰ τὴν Τεθμώσιος βασιλείαν ἀπαλλαγῆναί φησιν ἐξ Αἰγύπτου τοὺς Ἰουδαίους πρὸ ἐτῶν τριακοσίων ἐνενηκοντατριῶν τῆς εἰς Ἄργος Δαναοῦ φυγῆς, Λυσίμαχος δὲ κατὰ Βόκχοριν τὸν βασιλέα, τουτέστι πρὸ ἐτῶν χιλίων ἑπτακοσίων, Μόλων δὲ καὶ ἄλλοι τινὲς ὡς αὐτοῖς ἔδοξεν."},{"number":17,"text":"ὁ δέ γε πάντων πιστότατος Ἀπίων ὡρίσατο τὴν ἔξοδον ἀκριβῶς κατὰ τὴν ἑβδόμην ὀλυμπιάδα καὶ ταύτης ἔτος εἶναι πρῶτον, ἐν ᾧ, φησί, Καρχηδόνα Φοίνικες ἔκτισαν. τοῦτο δὲ πάντως προσέθηκε τὸ Καρχηδόνα τεκμήριον οἰόμενος αὑτῷ γενέσθαι τῆς ἀληθείας ἐναργέστατον, οὐ συνῆκε δὲ καθʼ ἑαυτοῦ τὸν ἔλεγχον ἐπισπώμενος."},{"number":18,"text":"εἰ γὰρ περὶ τῆς ἀπιστίας πιστεύειν δεῖ ταῖς Φοινίκων ἀναγραφαῖς, ἐν ἐκείναις Εἴρωμος ὁ βασιλεὺς γέγραπται πρεσβύτερος τῆς Καρχηδόνος κτίσεως ἔτεσι πλείοσι πρὸς τοῖς πεντήκοντα καὶ ἑκατόν, περὶ οὗ τὰς πίστεις ἀνωτέρω παρέσχον ἐκ τῶν Φοινίκων ἀναγραφῶν,"},{"number":19,"text":"ὅτι Σολομῶνι τῷ τὸν ναὸν οἰκοδομησαμένῳ τὸν ἐν Ἱεροσολύμοις φίλος ἦν Εἴρωμος καὶ πολλὰ συνεβάλετο πρὸς τὴν τοῦ ναοῦ κατασκευήν. αὐτὸς δὲ ὁ Σολομὼν ᾠκοδόμησε τὸν ναὸν μετὰ τὸ ἐξελθεῖν ἐξ Αἰγύπτου τοὺς Ἰουδαίους δώδεκα καὶ ἑξακοσίοις ἔτεσιν ὕστερον."},{"number":20,"text":"τὸν δὲ ἀριθμὸν τῶν ἐλαθέντων τὸν αὐτὸν Λυσιμάχῳ σχεδιάσας, ἕνδεκα γὰρ αὐτοὺς εἶναί φησι μυριάδας, θαυμαστήν τινα καὶ πιθανὴν ἀποδίδωσιν αἰτίαν, ἀφʼ ἧς φησι τὸ σάββατον ὠνομάσθαι."},{"number":21,"text":"ὁδεύσαντες γάρ, φησίν, ἓξ ἡμερῶν ὁδὸν βουβῶνας ἔσχον καὶ διὰ ταύτην τὴν αἰτίαν τῇ ἑβδόμῃ ἡμέρᾳ ἀνεπαύσαντο σωθέντες εἰς τὴν χώραν τὴν νῦν Ἰουδαίαν λεγομένην καὶ ἐκάλεσαν τὴν ἡμέραν σάββατον σώζοντες τὴν Αἰγυπτίων γλῶτταν· τὸ γὰρ βουβῶνος ἄλγος καλοῦσιν Αἰγύπτιοι σαββάτωσις."},{"number":22,"text":"οὐκ ἂν οὖν τις ἢ καταγελάσειε τῆς φλυαρίας ἢ τοὐναντίον μισήσειε τὴν ἐν τῷ τοιαῦτα γράφειν ἀναίδειαν; δῆλον γάρ, ὅτι πάντες ἐβουβωνίασαν ἕνδεκα μυριάδες ἀνθρώπων."},{"number":23,"text":"ἀλλʼ εἰ μὲν ἦσαν ἐκεῖνοι τυφλοὶ καὶ χωλοὶ καὶ πάντα τρόπον νοσοῦντες ὁποίους αὐτοὺς εἶναί φησιν Ἀπίων, οὐδʼ ἂν μιᾶς ἡμέρας προελθεῖν ὁδὸν ἠδυνήθησαν· εἰ δʼ οἷοι βαδίζειν διὰ πολλῆς ἐρημίας καὶ προσέτι νικᾶν τοὺς αὐτοῖς ἀνθισταμένους μαχόμενοι πάντες, οὐκ ἂν ἀθρόοι μετὰ τὴν ἕκτην ἡμέραν ἐβουβωνίασαν·"},{"number":24,"text":"οὔτε γὰρ φύσει πως γίνεται τὸ τοιοῦτον τοῖς βαδίζουσιν ἐξ ἀνάγκης, ἀλλὰ πολλαὶ μυριάδες στρατοπέδων ἐπὶ πολλὰς ἡμέρας τὸ σύμμετρον ἀεὶ βαδίζουσιν, οὔτε κατʼ αὐτόματον εἰκὸς οὕτως συμβῆναι· πάντων γὰρ ἀλογώτατον."},{"number":25,"text":"ὁ δὲ θαυμαστὸς Ἀπίων διὰ μὲν ἓξ ἡμερῶν αὐτοὺς ἐλθεῖν εἰς τὴν Ἰουδαίαν προείρηκε, πάλιν δὲ τὸν Μωσῆν εἰς τὸ μεταξὺ τῆς Αἰγύπτου καὶ τῆς Ἀραβίας ὄρος, ὃ καλεῖται Σίναιον, ἀναβάντα φησὶν ἡμέρας τεσσαράκοντα κρυβῆναι κἀκεῖθεν καταβάντα δοῦναι τοῖς Ἰουδαίοις τοὺς νόμους. καίτοι πῶς οἷόν τε τοὺς αὐτοὺς καὶ τεσσαράκοντα μένειν ἡμέρας ἐν ἐρήμῳ καὶ ἀνύδρῳ τόπῳ καὶ τὴν μεταξὺ πᾶσαν ἐν ἡμέραις ἓξ διελθεῖν;"},{"number":26,"text":"ἡ δὲ περὶ τὴν ὀνομασίαν τοῦ σαββάτου γραμματικὴ μετάθεσις ἀναίδειαν ἔχει πολλὴν ἢ δεινὴν ἀμαθίαν·"},{"number":27,"text":"τὸ γὰρ σαββὼ καὶ σάββατον πλεῖστον ἀλλήλων διαφέρει· τὸ μὲν γὰρ σάββατον κατὰ τὴν Ἰουδαίων διάλεκτον ἀνάπαυσίς ἐστιν ἀπὸ παντὸς ἔργου, τὸ δὲ σαββώ, καθάπερ ἐκεῖνός φησι, δηλοῖ παρʼ Αἰγυπτίοις τὸ βουβῶνος ἄλγος."},{"number":28,"text":"Τοιαῦτα μέν τινα περὶ Μωσέως καὶ τῆς ἐξ Αἰγύπτου γενομένης τοῖς Ἰουδαίοις ἀπαλλαγῆς ὁ Αἰγύπτιος Ἀπίων ἐκαινοποίησεν παρὰ τοὺς ἄλλους ἐπινοήσας. καὶ τί γε δεῖ θαυμάζειν, εἰ περὶ τῶν ἡμετέρων ψεύδεται προγόνων λέγων αὐτοὺς εἶναι τὸ γένος Αἰγυπτίους;"},{"number":29,"text":"αὐτὸς γὰρ περὶ αὐτοῦ τοὐναντίον ἐψεύδετο καὶ γεγενημένος ἐν Ὀάσει τῆς Αἰγύπτου πάντων Αἰγυπτίων πρῶτος ὤν, ὡς ἂν εἴποι τις, τὴν μὲν ἀληθῆ πατρίδα καὶ τὸ γένος ἐξωμόσατο, Ἀλεξανδρεὺς δὲ εἶναι καταψευδόμενος ὁμολογεῖ τὴν μοχθηρίαν τοῦ γένους."},{"number":30,"text":"εἰκότως οὖν οὓς μισεῖ καὶ βούλεται λοιδορεῖν τούτους Αἰγυπτίους καλεῖ· εἰ μὴ γὰρ φαυλοτάτους εἶναι ἐνόμιζεν Αἰγυπτίους, οὐκ ἂν τοῦ γένους αὐτὸς ἔφυγεν· ὡς οἵ γε μεγαλοφρονοῦντες ἐπὶ ταῖς ἑαυτῶν πατρίσι σεμνύνονται μὲν ἀπὸ τούτων αὐτοὶ χρηματίζοντες, τοὺς ἀδίκως δʼ αὐτῶν ἀντιποιουμένους ἐλέγχουσι."},{"number":31,"text":"πρὸς ἡμᾶς δὲ δυοῖν θάτερον Αἰγύπτιοι πεπόνθασιν· ἢ γὰρ ὡς ἐπισεμνυνόμενοι προσποιοῦνται τὴν συγγένειαν ἢ κοινωνοὺς ἡμᾶς ἐπισπῶνται τῆς αὑτῶν κακοδοξίας."},{"number":32,"text":"ὁ δὲ γενναῖος Ἀπίων δοκεῖ μὲν τὴν βλασφημίαν τὴν καθʼ ἡμῶν ὥσπερ τινὰ μισθὸν ἐθελῆσαι παρασχεῖν Ἀλεξανδρεῦσι τῆς δοθείσης αὐτῷ πολιτείας, καὶ τὴν ἀπέχθειαν αὐτῶν ἐπιστάμενος τὴν πρὸς τοὺς συνοικοῦντας αὐτοῖς ἐπὶ τῆς Ἀλεξανδρείας Ἰουδαίους προτέθειται μὲν ἐκείνοις λοιδορεῖσθαι, συμπεριλαμβάνειν δὲ καὶ τοὺς ἄλλους ἅπαντας, ἐν ἀμφοτέροις ἀναισχύντως ψευδόμενος."},{"number":33,"text":"Τίνα τοίνυν ἐστὶ τὰ δεινὰ καὶ σχέτλια τῶν ἐν Ἀλεξανδρείᾳ κατοικούντων Ἰουδαίων, ἃ κατηγόρηκεν αὐτῶν, ἴδωμεν. ἐλθόντες, φησίν, ἀπὸ Συρίας ᾤκησαν πρὸς ἀλίμενον θάλασσαν γειτνιάσαντες ταῖς τῶν κυμάτων ἐκβολαῖς."},{"number":34,"text":"οὐκοῦν τόπος εἰ λοιδορίαν ἔχει, τὴν οὐ πατρίδα μὲν λεγομένην δὲ αὐτοῦ λοιδορεῖ τὴν Ἀλεξάνδρειαν· ἐκείνης γὰρ καὶ τὸ παράλιόν ἐστι μέρος, ὡς πάντες ὁμολογοῦσιν, εἰς κατοίκησιν τὸ κάλλιστον."},{"number":35,"text":"Ἰουδαῖοι δʼ εἰ μὲν βιασάμενοι κατέσχον, ὡς μηδʼ ὕστερον ἐκπεσεῖν, ἀνδρείας τεκμήριόν ἐστιν αὐτοῖς· εἰς κατοίκησιν δὲ αὐτοῖς ἔδωκεν τόπον Ἀλέξανδρος καὶ ἴσης παρὰ τοῖς Μακεδόσι τιμῆς ἐπέτυχον."},{"number":36,"text":"οὐκ οἶδα δέ, τί ποτʼ ἂν ἔλεγεν Ἀπίων, εἰ πρὸς τῇ νεκροπόλει κατῴκουν καὶ μὴ πρὸς τοῖς βασιλικοῖς ἦσαν ἱδρυμένοι, καὶ μέχρι νῦν αὐτῶν ἡ φυλὴ τὴν προσηγορίαν εἶχεν Μακεδόνες."},{"number":37,"text":"εἰ μὲν οὖν ἀναγνοὺς τὰς ἐπιστολὰς Ἀλεξάνδρου τοῦ βασιλέως καὶ τὰς Πτολεμαίου τοῦ Λάγου καὶ τῶν μετʼ ἐκεῖνον τῆς Αἰγύπτου βασιλέων ἐντυχὼν τοῖς γράμμασι καὶ τὴν στήλην τὴν ἑστῶσαν ἐν Ἀλεξανδρείᾳ καὶ τὰ δικαιώματα περιέχουσαν, ἃ Καῖσαρ ὁ μέγας τοῖς Ἰουδαίοις ἔδωκεν, εἰ μὲν οὖν ταῦτα, φημί, γιγνώσκων τἀναντία γράφειν ἐτόλμα, πονηρὸς ἦν, εἰ δὲ μηδὲν ἠπίστατο τούτων, ἀπαίδευτος."},{"number":38,"text":"τὸ δὲ δὴ θαυμάζειν, πῶς Ἰουδαῖοι ὄντες Ἀλεξανδρεῖς ἐκλήθησαν, τῆς ὁμοίας ἀπαιδευσίας· πάντες γὰρ οἱ εἰς ἀποικίαν τινὰ κατακληθέντες, κἂν πλεῖστον ἀλλήλων τοῖς γένεσι διαφέρωσιν, ἀπὸ τῶν οἰκιστῶν τὴν προσηγορίαν λαμβάνουσιν."},{"number":39,"text":"καὶ τί δεῖ περὶ τῶν ἄλλων λέγειν; αὐτῶν γὰρ ἡμῶν οἱ τὴν Ἀντιόχειαν κατοικοῦντες Ἀντιοχεῖς ὀνομάζονται· τὴν γὰρ πολιτείαν αὐτοῖς ἔδωκεν ὁ κτίστης Σέλευκος. ὁμοίως οἱ ἐν Ἐφέσῳ καὶ κατὰ τὴν ἄλλην Ἰωνίαν τοῖς αὐθιγενέσι πολίταις ὁμωνυμοῦσιν τοῦτο παρασχόντων αὐτοῖς τῶν διαδόχων."},{"number":40,"text":"ἡ δὲ Ῥωμαίων φιλανθρωπία πᾶσιν οὐ μικροῦ δεῖν τῆς αὐτῶν προσηγορίας μεταδέδωκεν οὐ μόνον ἀνδράσιν ἀλλὰ καὶ μεγάλοις ἔθνεσιν ὅλοις; Ἴβηρες γοῦν οἱ πάλαι καὶ Τυρρηνοὶ καὶ Σαβῖνοι Ῥωμαῖοι καλοῦνται."},{"number":41,"text":"εἰ δὲ τοῦτον ἀφαιρεῖται τὸν τρόπον τῆς πολιτείας Ἀπίων, παυσάσθω λέγων αὑτὸν Ἀλεξανδρέα· γεννηθεὶς γάρ, ὡς προεῖπον, ἐν τῷ βαθυτάτῳ τῆς Αἰγύπτου πῶς ἂν Ἀλεξανδρεὺς εἴη τῆς κατὰ δόσιν πολιτείας, ὡς αὐτὸς ἐφʼ ἡμῶν ἠξίωκεν, ἀναιρουμένης; καίτοι μόνοις Αἰγυπτίοις οἱ κύριοι νῦν Ῥωμαῖοι τῆς οἰκουμένης μεταλαμβάνειν ἡστινοσοῦν πολιτείας ἀπειρήκασιν."},{"number":42,"text":"ὁ δʼ οὕτως ἐστὶ γενναῖος, ὡς μετέχειν ἀξιῶν αὐτὸς ὧν τυχεῖν ἐκωλύετο συκοφαντεῖν ἐπεχείρησε τοὺς δικαίως λαβόντας· οὐ γὰρ ἀπορίᾳ γε τῶν οἰκησόντων τὴν μετὰ σπουδῆς ὑπʼ αὐτοῦ πόλιν κτιζομένην Ἀλέξανδρος τῶν ἡμετέρων τινὰς ἐκεῖ συνήθροισεν, ἀλλὰ πάντας δοκιμάζων ἐπιμελῶς ἀρετῆς καὶ πίστεως τοῦτο τοῖς ἡμετέροις τὸ γέρας ἔδωκεν."},{"number":43,"text":"ἐτίμα γὰρ ἡμῶν τὸ ἔθνος, ὡς καί φησιν Ἑκαταῖος περὶ ἡμῶν, ὅτι διὰ τὴν ἐπιείκειαν καὶ πίστιν, ἣν αὐτῷ παρέσχον Ἰουδαῖοι, τὴν Σαμαρεῖτιν χώραν προσέθηκεν ἔχειν αὐτοῖς ἀφορολόγητον."},{"number":44,"text":"ὅμοια δὲ Ἀλεξάνδρῳ καὶ Πτολεμαῖος ὁ Λάγου περὶ τῶν ἐν Ἀλεξανδρείᾳ κατοικούντων ἐφρόνησεν· καὶ γὰρ τὰ κατὰ τὴν Αἴγυπτον αὐτοῖς ἐνεχείρισε φρούρια πιστῶς ἅμα καὶ γενναίως φυλάξειν ὑπολαμβάνων, καὶ Κυρήνης ἐγκρατῶς ἄρχειν βουλόμενος καὶ τῶν ἄλλων τῶν ἐν τῇ Λιβύῃ πόλεων εἰς αὐτὰς μέρος Ἰουδαίων ἔπεμψε κατοικῆσον."},{"number":45,"text":"ὁ δὲ μετʼ αὐτὸν Πτολεμαῖος ὁ Φιλάδελφος ἐπικληθεὶς οὐ μόνον εἴ τινες ἦσαν αἰχμάλωτοι παρʼ αὐτῷ τῶν ἡμετέρων πάντας ἀπέδωκεν, ἀλλὰ καὶ χρήματα πολλάκις ἐδωρήσατο καὶ τὸ μέγιστον ἐπιθυμητὴς ἐγένετο τοῦ γνῶναι τοὺς ἡμετέρους νόμους καὶ ταῖς τῶν ἱερῶν γραφῶν βίβλοις ἐντυχεῖν."},{"number":46,"text":"ἔπεμψε γοῦν ἀξιῶν ἄνδρας ἀποσταλῆναι τοὺς ἑρμηνεύσοντας αὐτῷ τὸν νόμον καὶ τοῦ γραφῆναι ταῦτα καλῶς τὴν ἐπιμέλειαν ἐπέταξεν οὐ τοῖς τυχοῦσιν, ἀλλὰ Δημήτριον τὸν Φαληρέα καὶ Ἀνδρέαν καὶ Ἀριστέα, τὸν μὲν παιδείᾳ τῶν καθʼ ἑαυτὸν διαφέροντα Δημήτριον,"},{"number":47,"text":"τοὺς δὲ τὴν τοῦ σώματος αὐτοῦ φυλακὴν ἐγκεχειρισμένους, ἐπὶ τῆς ἐπιμελείας ταύτης ἔταξεν, οὐκ ἂν δήπου τοὺς νόμους καὶ τὴν πάτριον ἡμῶν φιλοσοφίαν ἐπιθυμήσας ἐκμαθεῖν, εἰ τῶν χρωμένων αὐτοῖς ἀνδρῶν κατεφρόνει καὶ μὴ λίαν ἐθαύμαζεν."},{"number":48,"text":"Ἀπίωνα δὲ σχεδὸν ἐφεξῆς πάντες ἔλαθον οἱ τῶν προγόνων αὐτοῦ Μακεδόνων βασιλεῖς οἰκειότατα πρὸς ἡμᾶς διατεθέντες· καὶ γὰρ τρίτος Πτολεμαῖος ὁ λεγόμενος Εὐεργέτης κατασχὼν ὅλην Συρίαν κατὰ κράτος οὐ τοῖς ἐν Αἰγύπτῳ θεοῖς χαριστήρια τῆς νίκης ἔθυσεν, ἀλλὰ παραγενόμενος εἰς Ἱεροσόλυμα πολλὰς ὡς ἡμῖν νόμιμόν ἐστιν ἐπετέλεσε θυσίας τῷ θεῷ καὶ ἀνέθηκεν ἀναθήματα τῆς νίκης ἀξίως."},{"number":49,"text":"ὁ δὲ Φιλομήτωρ Πτολεμαῖος καὶ ἡ γυνὴ αὐτοῦ Κλεοπάτρα τὴν βασιλείαν ὅλην τὴν ἑαυτῶν Ἰουδαίοις ἐπίστευσαν, καὶ στρατηγοὶ πάσης τῆς δυνάμεως ἦσαν Ὀνίας καὶ Δοσίθεος Ἰουδαῖοι, ὧν Ἀπίων σκώπτει τὰ ὀνόματα, δέον τὰ ἔργα θαυμάζειν καὶ μὴ λοιδορεῖν, ἀλλὰ χάριν αὐτοῖς ἔχειν, ὅτι διέσωσαν τὴν Ἀλεξάνδρειαν, ἧς ὡς πολίτης ἀντιποιεῖται."},{"number":50,"text":"πολεμούντων γὰρ αὐτῶν τῇ βασιλίσσῃ Κλεοπάτρᾳ καὶ κινδυνευόντων ἀπολέσθαι κακῶς οὗτοι συμβάσεις ἐποίησαν καὶ τῶν ἐμφυλίων κακῶν ἀπήλλαξαν. ἀλλὰ μετὰ ταῦτα, φησίν, Ὀνίας ἐπὶ τὴν πόλιν ἤγαγε στρατὸν ὀλίγον ὄντος ἐκεῖ Θέρμου τοῦ παρὰ Ῥωμαίων πρεσβευτοῦ καὶ παρόντος."},{"number":51,"text":"ὀρθῶς δὲ ποιῶν φαίην ἂν καὶ μάλα δικαίως· ὁ γὰρ Φύσκων ἐπικληθεὶς Πτολεμαῖος ἀποθανόντος αὐτῷ τοῦ ἀδελφοῦ Πτολεμαίου τοῦ Φιλομήτορος ἀπὸ Κυρήνης ἐξῆλθε Κλεοπάτραν ἐκβαλεῖν βουλόμενος τῆς βασιλείας et filios regis, ut ipse regnum iniuste sibimet applicaret;"},{"number":52,"text":"propter haec ergo Onias aduersus eum bellum pro Cleopatra suscepit et fidem, quam habuit circa reges, nequaquam in necessitate deseruit."},{"number":53,"text":"testis autem deus iustitiae eius manifestus apparuit; nam Fyscon Ptolomaeus cum aduersum exercitum quidem Oniae pugnare praesumeret, omnes uero Iudaeos in ciuitate positos cum filiis et uxoribus capiens nudos atque uinctos elephantis subiecisset, ut ab eis conculcati deficerent, et ad hoc etiam bestias ipsas debriasset, in contrarium quae praeparauerat euenerunt."},{"number":54,"text":"elephanti enim relinquentes sibi appositos Iudaeos impetu facto super amicos eius multos ex ipsis interemerunt. et post haec Ptolomaeus quidem aspectum terribilem contemplatus est prohibentem se, ut illis noceret hominibus;"},{"number":55,"text":"concubina uero sua carissima, quam alii quidem Ithacam, alii uero Hirenen denominant, supplicante ne tantam impietatem perageret, ei concessit et ex his quae iam egerat uel acturus erat paenitentiam egit. unde recte hanc diem Iudaei Alexandria constituti eo quod aperte a deo salutem promeruerunt celebrare noscuntur."},{"number":56,"text":"Apion autem omnium calumniator etiam propter bellum aduersus Fysconem gestum Iudaeos accusare praesumpsit, cum eos laudare debuerit. is autem etiam ultimae Cleopatrae Alexandrinorum reginae meminit ueluti nobis improperans, quoniam circa nos fuit ingrata, et non potius illam redarguere studuit;"},{"number":57,"text":"cui nihil omnino iniustitiae et malorum operum defuit uel circa generis necessarios uel circa maritos suos, qui etiam dilexerunt eam, uel in communi contra Romanos omnes et benefactores suos imperatores, quae etiam sororem Arsinoën occidit in templo nihil sibi nocentem,"},{"number":58,"text":"peremit autem et fratrem insidiis paternosque deos et sepulcra progenitorum depopulata est, percipiensque regnum a primo Caesare eius filio et successori rebellare praesumpsit, Antoniumque corrumpens amatoriis rebus et patriae inimicum fecit et infidelem circa suos amicos instituit, alios quidem genere regali spolians, alios autem demens et ad mala gerenda compellens."},{"number":59,"text":"sed quid oportet amplius dici, cum illum ipsum in nauali certamine relinquens, id est maritum et parentem communium filiorum, tradere eum exercitum et principatum et se sequi coëgit?"},{"number":60,"text":"nouissime uero Alexandria a Caesare capta ad hoc usque perducta est, ut salutem hinc sperare se iudicaret, si posset ipsa manu sua Iudaeos perimere, eo quod circa omnes crudelis et infidelis extaret. putasne gloriandum nobis non esse, si quemadmodum dicit apion famis tempore iudaeis triticum non est mensa?"},{"number":61,"text":"sed illa quidem poenam subiit competentem, nos autem maximo Caesare utimur teste solatii atque fidei, quam circa eum contra Aegyptios gessimus, necnon et senatu eiusque dogmatibus et epistulis Caesaris Augusti, quibus nostra merita comprobantur."},{"number":62,"text":"has litteras Apionem oportebat inspicere et secundum genera examinare testimonia sub Alexandro facta et omnibus Ptolomaeis et quae a senatu constituta sunt necnon et a maximis Romanis imperatoribus."},{"number":63,"text":"si uero Germanicus frumenta cunctis in Alexandria commorantibus metiri non potuit, hoc indicium est sterilitatis ac necessitatis frumentorum, non accusatio Iudaeorum. quid enim sapiant omnes imperatores de Iudaeis in Alexandria commorantibus, palam est;"},{"number":64,"text":"nam amministratio tritici nihilo minus ab eis quam ab aliis Alexandrinis translata est, maximam uero eis fidem olim a regibus datam conseruauerunt, id est fluminis custodiam totiusque custodiae nequaquam his rebus indignos esse iudicantes."},{"number":65,"text":"sed super haec, quomodo ergo, inquit, si sunt ciues, eosdem deos quos Alexandrini non colunt? cui respondeo, quomodo etiam, cum uos sitis Aegyptii, inter alterutros proelio magno et sine foedere de religione contenditis?"},{"number":66,"text":"an certe propterea non uos omnes dicimus aegyptios et neque communiter homines, quoniam bestias aduersantes naturae nostrae colitis multa diligentia nutrientes, cum genus utique nostrorum unum itaque idem esse uideatur?"},{"number":67,"text":"si autem in uobis Aegyptiis tantae differentiae opinionum sunt, quid miraris super his, qui aliunde in Alexandriam aduenerunt, si in legibus a principio constitutis circa talia permanserunt?"},{"number":68,"text":"is autem etiam seditionis causas nobis apponit, qui si cum ueritate ob hoc accusat Iudaeos in Alexandria constitutos, cur omnes nos culpat ubique positos"},{"number":69,"text":"eo quod noscamur habere concordiam? porro etiam seditionis auctores quilibet inueniet Apioni similes Alexandrinorum fuisse ciues. donec enim graeci fuerunt et Macedones hanc ciuilitatem habentes, nullam seditionem aduersus nos gesserunt, sed antiquis cessere sollemnitatibus. cum uero multitudo Aegyptiorum creuisset inter eos propter confusiones temporum, etiam hoc opus semper est additum. nostrum uero genus permansit purum."},{"number":70,"text":"ipsi igitur molestiae huius fuere principium nequaquam populo Macedonicam habente constantiam neque prudentiam Graecam, sed cunctis scilicet utentibus malis moribus Aegyptiorum et antiquas inimicitias aduersum nos exercentibus."},{"number":71,"text":"e diuerso namque factum est quod nobis improperare praesumunt; nam cum plurimi eorum non oportune ius eius ciuilitatis optineant, peregrinos uocant eos, qui hoc priuilegium ad omnes imperasse noscuntur."},{"number":72,"text":"nam Aegyptiis neque regum quisquam uidetur ius ciuilitatis fuisse largitus neque nunc quilibet imperatorum, nos autem Alexander quidem introduxit, reges autem auxerunt, Romani uero semper custodire dignati sunt."},{"number":73,"text":"itaque derogare nobis apion conatus est, quia imperatorum non statuamus imagines tamquam illis hoc ignorantibus aut defensione Apionis indigentibus, cum potius debuerit ammirari magnanimitatem mediocritatemque romanorum, quoniam subiectos non cogunt patria iura transcendere, sed suscipiunt honores sicut dare offerentes pium atque legitimum est; non enim honoribus gratiam habent, qui ex necessitate et uiolentia conferuntur."},{"number":74,"text":"Graecis itaque et aliis quibusdam bonum esse creditur imagines instituere, denique et patrum et uxorum filiorumque figuras depingentes exultant, quidam uero etiam nihil sibi competentium sumunt imagines, alii uero et seruos diligentes hoc faciunt. quid ergo mirum est, si etiam principibus ac dominis hunc honorem praebere uideantur?"},{"number":75,"text":"porro noster legislator, non quasi prophetans romanorum potentiam non honorandam, sed tamquam causam neque deo neque hominibus utilem despiciens, et quoniam totius animati, multo magis dei inanimatu probatur inferius interdixit imagines fabricari."},{"number":76,"text":"aliis autem honoribus post deum colendos non prohibuit uiros bonos, quibus nos et imperatores et populum Romanorum dignitatibus ampliamus."},{"number":77,"text":"facimus autem pro eis continua sacrificia et non solum cotidianis diebus ex impensa communi omnium Iudaeorum talia celebramus, uerum cum nullas alias hostias ex communi neque pro filiis peragamus, solis imperatoribus hunc honorem praecipuum pariter exhibemus, quem hominum nulli persoluimus."},{"number":78,"text":"haec itaque communiter satisfactio posita sit aduersus Apionem pro his, quae de Alexandria dicta sunt."},{"number":79,"text":"ammiror autem etiam eos, qui ei huiusmodi fomitem praebuerunt id est Posidonium et Apollonium Molonis, quoniam accusant quidem nos, quare nos eosdem deos cum aliis non colimus, mentientes autem pariter et de nostro templo blasphemias componentes incongruas non se putant impie agere, dum sit ualde turpissimum liberis qualibet ratione mentiri multo magis de templo apud cunctos homines nominato tanta sanctitate pollente."},{"number":80,"text":"in hoc enim sacrario Apion praesumpsit edicere asini caput collocasse Iudaeos et eum colere ac dignum facere tanta religione, et hoc affirmat fuisse depalatum, dum Antiochus epiphanes expoliasset templum et illud caput inuentum ex auro compositum multis pecuniis dignum."},{"number":81,"text":"ad haec igitur prius equidem dico, quoniam Aegyptius, uel si aliquid tale apud nos fuisset, nequaquam debuerat increpare, cum non sit deterior asinus furonibus et hircis et aliis, quae sunt apud eos dii."},{"number":82,"text":"deinde quomodo non intellexit operibus increpatus de incredibili suo mendacio? legibus namque semper utimur hisdem, in quibus sine fine consistimus, et cum uarii casus nostram ciuitatem sicut etiam aliorum uexauerint et Pius ac Pompeius Magnus et Licinius crassus et ad nouissimum Titus Caesar bello uincentes optinuerint templum, nihil huiusmodi illic inuenerunt, sed purissimam pietatem, de qua nihil nobis est apud alios effabile."},{"number":83,"text":"quia uero Antiochus neque iustam fecit templi depraedationem, sed egestate pecuniarum ad hoc accessit, cum non esset hostis, et super nos auxiliatores suos et amicos adgressus est nec aliquid dignum derisione illic inuenit,"},{"number":84,"text":"multi et digni conscriptores super hoc quoque testantur, Polybius Megalopolita Strabon Cappadox Nicolaus Damascenus Timagenis et Castor temporum conscriptor et Apollodorus; omnes dicunt pecuniis indigentem Antiochum transgressum foedera Iudaeorum et spoliasse templum auro Argentoque plenum."},{"number":85,"text":"haec igitur Apion debuit respicere, nisi cor asini ipse potius habuisset et impudentiam canis, qui apud ipsos assolet coli; neque enim extrinsecus aliqua ratiocinatione mentitus est."},{"number":86,"text":"nos itaque asinis neque honorem neque potestatem aliquam damus, sicut Aegyptii crocodillis et aspidibus, quando eos qui ab istis mordentur et a crocodillis rapiuntur felices et deo digni arbitrantur."},{"number":87,"text":"sed sunt apud nos asini quod apud alios sapientes uiros onera sibimet imposita sustinentes, et licet ad areas accedentes comedant aut uiam propositam non adimpleant, multas ualde plagas accipiunt quippe operibus et ad agriculturam rebus necessariis ministrantes."},{"number":88,"text":"sed aut omnium gurdissimus fuit Apion ad componendum uerba fallacia aut certe ex rebus initia sumens haec implere non ualuit, quando nulla potest contra nos blasphemia prouenire."},{"number":89,"text":"alteram uero fabulam derogatione nostra plenam de Graecis apposuit, de quo hoc dicere sat erit, quoniam qui de pietate loqui praesumunt oportet eos non ignorare minus esse inmundum per templa transire quam sacerdotibus scelesta uerba componere."},{"number":90,"text":"isti uero magis studuerunt defendere sacrilegum regem quam iusta et ueracia de nostris et de templo conscribere; uolentes enim Antiocho praestare et infidelitatem ac sacrilegium eius tegere, quo circa gentem nostram est usus propter egestatem pecuniarum, detrahentes nobis etiam quae in futuro essent dicenda mentiti sunt."},{"number":91,"text":"propheta uero aliorum factus est Apion et dixit Antiochum in templo inuenisse lectum et hominem in eo iacentem et propositam ei mensam maritimis terrenisque et uolatilium dapibus plenam, et obstipuisset his homo."},{"number":92,"text":"illum uero mox adorasse regis ingressum tamquam maximum ei solacium praebiturum ac procidentem ad eius genua extensa dextra poposcisse libertatem; et iubente rege, ut confideret et diceret, quis esset uel cur ibidem habitaret uel quae esset causa ciborum eius, tunc hominem cum gemitu et lacrimis lamentabiliter suam narrasse necessitatem ait."},{"number":93,"text":"inquit esse quidem se Graecum, et dum peragraret prouinciam propter uitae causam direptum se subito ab alienigenis hominibus atque deductum ad templum et inclusum illic, et a nullo conspici sed cuncta dapium praeparatione saginari."},{"number":94,"text":"et primum quidem haec sibi inopinabilia beneficia prodidisse et detulisse laetitiam deinde suspicionem postea stuporem, ac postremum consulentem a ministris ad se accedentibus audisse legem ineffabilem Iudaeorum, pro qua nutriebatur, et hoc illos facere singulis annis quodam tempore constituto."},{"number":95,"text":"et compraehendere quidem Graecum peregrinum eumque annali tempore saginare et deductum ad quandam siluam occidere quidem eum hominem eiusque corpus sacrificare secundum suas sollemnitates et gustare ex eius uisceribus et iusiurandum facere in immolatione Graeci, ut inimicitias contra Graecos haberent, et tunc in quandam foueam reliqua hominis pereuntis abicere."},{"number":96,"text":"deinde refert eum dixisse paucos iam dies debita sibimet superesse atque rogasse, ut erubescens Graecorum deos et superantes in suo sanguine insidias Iudaeorum de malis eum circumastantibus liberaret."},{"number":97,"text":"huiusmodi ergo fabula non tantum omni tragoedia plenissima est, sed etiam impudentia crudeli redundat, non tamen a sacrilegio priuat Antiochum, sicut arbitrati sunt qui haec ad illius gratiam conscripserunt;"},{"number":98,"text":"non enim praesumpsit aliquid tale, ut ad templum accederet, sed sicut aiunt inuenit non sperans. fuit ergo uoluntate iniquus impius et nihilominus sine deo, quanta iussit mendacii superfluitas, quam ex ipsa re cognoscere ualde facillimum est."},{"number":99,"text":"non enim circa solos Graecos discordia legum esse dinoscitur, sed maxime aduersus Aegyptios et plurimos alios. *quem enim horum non contigit aliquando circa nos peregrinari, ut aduersus solos renouata coniuratione per"},{"number":100,"text":"effusionem sanguinis egeremus? uel quomodo possibile est, ut ad has hostias omnes Iudaei colligerentur et tantis milibus ad gustandum uiscera illa sufficerent, sicut ait Apion?"},{"number":101,"text":"uel cur inuentum hominem quicumque fuit, non enim suo nomine conscripsit, *aut quomodo eum in suam patriam rex non cum pompa deduxit, dum posset hoc faciens ipse quidem putari pius et Graecorum amator eximius, assumere uero contra Iudaeorum odium solacia magna cunctorum?"},{"number":102,"text":"sed haec relinquo; insensatos enim non uerbis sed operibus decet arguere. sciunt igitur omnes qui uiderunt constructionem templi nostri, qualis fuerit, et intransgressibilem eius purificationis integritatem."},{"number":103,"text":"quattuor etenim habuit in circuitu porticus, et harum singulae propriam secundum legem habuere custodiam; in exteriorem itaque ingredi licebat omnibus etiam alienigenis; mulieres tantummodo menstruatae transire prohibebantur."},{"number":104,"text":"in secunda uero porticu cuncti Iudaei ingrediebantur eorumque coniuges, cum essent ab omni pollutione mundae, in tertia masculi Iudaeorum mundi existentes atque purificati, in quartam autem sacerdotes stolis induti sacerdotalibus, in adytum uero soli principes sacerdotum propria stola circumamicti."},{"number":105,"text":"tanta uero est circa omnia prouidentia pietatis, ut secundum quasdam horas sacerdotes ingredi constitutum sit; mane etenim aperto templo oportebat facientes traditas hostias introire et meridie rursus, dum clauderetur templum."},{"number":106,"text":"denique nec uas aliquod portari licet in templum, sed erant in eo solummodo posita altare mensa turibulum candelabrum, quae omnia et in lege conscripta sunt."},{"number":107,"text":"etenim nihil amplius neque mysteriorum aliquorum ineffabilium agitur neque intus ulla epulatio ministratur; haec enim quae praedicta sunt habent totius populi testimonium manifestationemque gestorum."},{"number":108,"text":"licet enim sint tribus quattuor sacerdotum et harum tribuum singulae habeant hominum plus quam quinque milia, fit tamen obseruatio particulariter per dies certos, et his transactis alii succedentes ad sacrificia ueniunt et congregati in templum mediante die a praecedentibus claues templi et ad numerum omnia uasa percipiunt, nulla re, quae ad cibum aut potum adtineat, in templo delata."},{"number":109,"text":"talia namque etiam ad altare offerre prohibitum est praeter illa, quae ad sacrificia praeparantur. quid ergo Apionem esse dicimus nisi nihil horum examinantem uerba incredula protulisse? sed turpe est; historiae enim ueram notitiam se proferre grammaticus non promisit."},{"number":110,"text":"et sciens templi nostri pietatem hanc quidem praetermisit, hominis autem Graeci compraehensionem finxit et pabulum ineffabile et ciborum opulentissimam claritatem et seruos ingredientes ubi nec nobilissimos Iudaeorum licet intrare, nisi fuerint sacerdotes."},{"number":111,"text":"hoc ergo pessima est impietas atque mendacium spontaneum ad eorum seductionem, qui noluerint discutere ueritatem. per ea siquidem mala et ineffabilia, quae praedicta sunt, nobis detrahere temptauerunt."},{"number":112,"text":"rursumque tamquam piissimus deridet adiciens fabulae suae Mnaseam. ait enim illum retulisse, dum bellum Iudaei contra Iudaeos haberent longo quodam tempore in aliqua ciuitate Iudaeorum, qui Dorii nominantur, quendam eorum qui in ea Apollinem colebat uenisse ad Iudaeos, cuius hominis nomen dicit Zabidon deinde qui eis promisisset traditurum se eis Apollinem deum Doriensium uenturumque illum ad nostrum templum, si omnes abscederent."},{"number":113,"text":"et credidisse omnem multitudinem Iudaeorum; Zabidon uero fecisse quoddam machinamentum ligneum et circumposuisse sibi et in eo tres ordines infixisse lucernarum et ita ambulasse, ut procul stantibus appareret, quasi stellae per terram τὴν πορείαν ποιουμένων,"},{"number":114,"text":"τοὺς μὲν Ἰουδαίους ὑπὸ τοῦ παραδόξου τῆς θέας καταπεπληγμένους πόρρω μένοντας ἡσυχίαν ἄγειν, τὸν δὲ Ζάβιδον ἐπὶ πολλῆς ἡσυχίας εἰς τὸν ναὸν παρελθεῖν καὶ τὴν χρυσῆν ἀποσῦραι τοῦ κάνθωνος κεφαλήν, οὕτω γὰρ ἀστεϊζόμενος γέγραφεν, καὶ πάλιν εἰς Δῶρα τὸ τάχος ἀπελθεῖν."},{"number":115,"text":"ἆρα οὖν καὶ ἡμεῖς ἂν εἴποιμεν, ὅτι τὸν κάνθωνα τουτέστιν ἑαυτὸν Ἀπίων ἐπιφορτίζει καὶ ποιεῖ τῆς μωρολογίας ἅμα καὶ τῶν ψευσμάτων κατάγομον; καὶ γὰρ τόπους οὐκ ὄντας γράφει καὶ πόλεις οὐκ εἰδὼς μετατίθησιν."},{"number":116,"text":"ἡ μὲν γὰρ Ἰδουμαία τῆς ἡμετέρας χώρας ἐστὶν ὅμορος κατὰ Γάζαν κειμένη, καὶ Δῶρα ταύτης ἐστὶν οὐδεμία πόλις, τῆς μέντοι Φοινίκης παρὰ τὸ Καρμήλιον ὄρος Δῶρα πόλις ὀνομάζεται μηδὲν ἐπικοινωνοῦσα τοῖς Ἀπίωνος φλυαρήμασι· τεσσάρων γὰρ ἡμερῶν ὁδὸν τῆς Ἰουδαίας ἀφέστηκεν."},{"number":117,"text":"τί δʼ ἡμῶν ἔτι κατηγορεῖ τὸ μὴ κοινοὺς ἔχειν τοῖς ἄλλοις θεούς, εἰ ῥᾳδίως οὕτως ἐπείσθησαν οἱ πατέρες ἡμῶν ἥξειν τὸν Ἀπόλλωνα πρὸς αὐτοὺς καὶ μετὰ τῶν ἄστρων ἐπὶ τῆς γῆς ᾠήθησαν ὁρᾶν αὐτὸν περιπατοῦντα;"},{"number":118,"text":"λύχνον γὰρ οὐδέπω δῆλον ὅτι πρόσθεν ἑωράκασιν οἱ τὰς τοσαύτας καὶ τηλικαύτας λυχνοκαΐας ἐπιτελοῦντες, ἀλλʼ οὐδέ τις αὐτῷ βαδίζοντι κατὰ τὴν χώραν τῶν τοσούτων μυριάδων ὑπήντησεν, ἔρημα δὲ καὶ τὰ τείχη φυλάκων εὗρε πολέμου συνεστηκότος, ἐῶ τἆλλα."},{"number":119,"text":"τοῦ ναοῦ δʼ αἱ θύραι τὸ μὲν ὕψος ἦσαν ἑξήκοντα πηχῶν, εἴκοσι δὲ τὸ πλάτος, κατάχρυσοι δὲ πᾶσαι καὶ μικροῦ δεῖν σφυρήλατοι· ταύτας ἔκλειον οὐκ ἐλάττους ὄντες ἄνδρες διακόσιοι καθʼ ἑκάστην ἡμέραν καὶ τὸ καταλιπεῖν ἠνοιγμένας ἦν ἀθέμιτον."},{"number":120,"text":"ῥᾳδίως οὖν αὐτὰς ὁ λυχνοφόρος ἐκεῖνος ἀνοίξειν οἰόμενος καὶ τὴν τοῦ κάνθωνος ὡς ᾤετο κεφαλὴν ἔχων. πότερον οὖν αὐτὴν πάλιν ὡς ἡμᾶς ἀνέστρεψεν ἢ λαβὼν ἀπιὼν αὐτὴν εἰσεκόμισεν, ἵνα Ἀντίοχος εὕρῃ πρὸς δευτέραν Ἀπίωνι μυθολογίαν."},{"number":121,"text":"καταψεύσασθαί τινα καὶ ὅρκον ἡμῶν ὡς ὀμνυόντων τὸν θεὸν τὸν ποιήσαντα τὸν οὐρανὸν καὶ τὴν γῆν καὶ τὴν θάλασσαν μηδενὶ εὐνοήσειν ἀλλοφύλῳ, μάλιστα δὲ Ἕλλησιν."},{"number":122,"text":"ἔδει δὲ καταψευδόμενον ἅπαξ εἰπεῖν μηδενὶ εὐνοήσειν ἀλλοφύλῳ, μάλιστα δʼ Αἰγυπτίοις· οὕτως γὰρ ἂν τοῖς ἐξ ἀρχῆς αὐτοῦ πλάσμασιν ἥρμοττεν τὰ περὶ τὸν ὅρκον, εἴπερ ἦσαν ὑπὸ Αἰγυπτίων τῶν συγγενῶν οἱ πατέρες ἡμῶν οὐχὶ διὰ πονηρίαν ἀλλʼ ἐπὶ συμφοραῖς ἐξεληλαμένοι."},{"number":123,"text":"τῶν Ἑλλήνων δὲ πλέον τοῖς τόποις ἢ τοῖς ἐπιτηδεύμασιν ἀφεστήκαμεν, ὥστε μηδεμίαν ἡμῖν εἶναι πρὸς αὐτοὺς ἔχθραν μηδὲ ζηλοτυπίαν. τοὐναντίον μέντοι πολλοὶ παρʼ αὐτῶν εἰς τοὺς ἡμετέρους νόμους συνέβησαν εἰσελθεῖν, καί τινες μὲν ἐνέμειναν, εἰσὶ δʼ οἳ τὴν καρτερίαν οὐχ ὑπομείναντες πάλιν ἀπέστησαν."},{"number":124,"text":"καὶ τούτων οὐδεὶς πώποτε τὸν ὅρκον εἶπεν ἀκοῦσαι παρʼ ἡμῖν ὀμωμοσμένον, ἀλλὰ μόνος Ἀπίων, ὡς ἔοικεν, ἤκουσεν· αὐτὸς γὰρ ὁ συνθεὶς αὐτὸν ἦν."},{"number":125,"text":"Σφόδρα τοίνυν τῆς πολλῆς συνέσεως καὶ ἐπὶ τῷ μέλλοντι ῥηθήσεσθαι θαυμάζειν ἄξιόν ἐστιν Ἀπίωνα· τεκμήριον γὰρ εἶναί φησιν τοῦ μήτε νόμοις ἡμᾶς χρῆσθαι δικαίοις μήτε τὸν θεὸν εὐσεβεῖν ὡς προσῆκεν, δουλεύειν δὲ μᾶλλον ἔθνεσιν [καὶ] ἄλλοτε ἄλλοις καὶ τὸ κεχρῆσθαι συμφοραῖς τισι περὶ τὴν πόλιν, αὐτοὶ δῆλον ὅτι πόλεως ἡγεμονικωτάτης Ῥωμαίοις ἐκ τῶν ἄνωθεν ἄρχειν, ἀλλὰ μὴ δουλεύειν συνειθισμένων·"},{"number":126,"text":"καίτοι τούτων ἄν τις ἀπόσχοιτο τοιαύτης μεγαλοψυχίας. τῶν μὲν γὰρ ἄλλων οὐκ ἔστιν ὅστις ἀνθρώπων οὐχ ἱκανῶς καθʼ αὑτοῦ φαίη τοῦτον ὑπʼ Ἀπίωνος λελέχθαι τὸν λόγον·"},{"number":127,"text":"ὀλίγοις μὲν γὰρ ὑπῆρξεν ἐφʼ ἡγεμονίας διακαιροπτίας γενέσθαι, καὶ τούτους αἱ μεταβολαὶ πάλιν ἄλλοις δουλεύειν ὑπέζευξαν, τὸ πλεῖστον δὲ φῦλον ἄλλων ὑπακήκοεν πολλάκις."},{"number":128,"text":"Αἰγύπτιοι δʼ ἄρα μόνοι διὰ τὸ καταφυγεῖν, ὥς φασιν, εἰς τὴν χώραν αὐτῶν τοὺς θεοὺς καὶ σωθῆναι μεταβάλλοντας εἰς μορφὰς θηρίων ἐξαίρετον γέρας εὕροντο τὸ μηδενὶ δουλεῦσαι τῶν τῆς Ἀσίας ἢ τῆς Εὐρώπης κρατησάντων, οἱ μίαν ἡμέραν ἐκ τοῦ παντὸς αἰῶνος ἐλευθερίας οὐ τυχόντες ἀλλʼ οὐδὲ παρὰ τῶν οἰκοδεσποτῶν."},{"number":129,"text":"ὅντινα μὲν γὰρ αὐτοῖς ἐχρήσαντο Πέρσαι τρόπον οὐχ ἅπαξ μόνον ἀλλὰ καὶ πολλάκις πορθοῦντες τὰς πόλεις ἱερὰ κατασκάπτοντες τοὺς παρʼ αὐτοῖς νομιζομένους θεοὺς κατασφάζοντες, οὐκ ἂν ὀνειδίσαιμι·"},{"number":130,"text":"μιμεῖσθαι γὰρ οὐ προσῆκεν τὴν Ἀπίωνος ἀπαιδευσίαν, ὃς οὔτε τὰς Ἀθηναίων τύχας οὔτε τὰς Λακεδαιμονίων ἐνενόησεν, ὧν τοὺς μὲν ἀνδρειοτάτους εἶναι, τοὺς δὲ εὐσεβεστάτους τῶν Ἑλλήνων ἅπαντες λέγουσιν."},{"number":131,"text":"ἐῶ βασιλέας τοὺς ἐπʼ εὐσεβείᾳ διαβοηθέντας [ὧν ἕνα Κροῖσον], οἵαις ἐχρήσαντο συμφοραῖς βίου· ἐῶ τὴν καταπρησθεῖσαν Ἀθηναίων ἀκρόπολιν, τὸν ἐν Ἐφέσῳ ναόν, τὸν ἐν Δελφοῖς, ἄλλους μυρίους, καὶ οὐδεὶς ὠνείδισεν ταῦτα τοῖς παθοῦσιν, ἀλλὰ τοῖς δράσασιν."},{"number":132,"text":"καινὸς δὲ κατήγορος ἡμῶν Ἀπίων ηὑρέθη τῶν ἰδίων αὐτοῦ περὶ τὴν Αἴγυπτον κακῶν ἐκλαθόμενος, ἀλλὰ Σέσωστρις αὐτὸν ὁ μυθευόμενος Αἰγύπτου βασιλεὺς ἐτύφλωσεν· ἡμεῖς δὲ τοὺς ἡμετέρους οὐκ ἂν εἴποιμεν βασιλέας Δαυίδην καὶ Σολομῶνα πολλὰ χειρωσαμένους ἔθνη."},{"number":133,"text":"τούτους μὲν οὖν παραλίπωμεν· τὰ δὲ γνώριμα πᾶσιν Ἀπίων ἠγνόηκεν, ὅτι Περσῶν καὶ μετʼ ἐκείνους ἡγουμένων τῆς Ἀσίας Μακεδόνων Αἰγύπτιοι μὲν ἐδούλευον ἀνδραπόδων οὐδὲν διαφέροντες,"},{"number":134,"text":"ἡμεῖς δὲ ὄντες ἐλεύθεροι προσέτι καὶ τῶν πέριξ πόλεων ἤρχομεν ἔτη σχεδὸν εἴκοσί που καὶ ρ μέχρι Μάγνου Πομπηίου, καὶ πάντων ἐκπολεμηθέντων πρὸς Ῥωμαίων τῶν πανταχοῦ βασιλέων μόνοι διὰ πίστιν οἱ παρʼ ἡμῖν σύμμαχοι καὶ φίλοι διεφυλάχθησαν."},{"number":135,"text":"Ἀλλὰ θαυμαστοὺς ἄνδρας οὐ παρεσχήκαμεν οἷον τεχνῶν τινων εὑρετὰς ἢ σοφίᾳ διαφέροντας. καὶ καταριθμεῖ Σωκράτην καὶ Ζήνωνα καὶ Κλεάνθην καὶ τοιούτους τινάς. εἶτα τὸ θαυμασιώτατον τοῖς εἰρημένοις αὐτὸς ἑαυτὸν προστίθησι καὶ μακαρίζει τὴν Ἀλεξάνδρειαν, ὅτι τοιοῦτον ἔχει πολίτην·"},{"number":136,"text":"ἔδει γὰρ αὐτῷ μάρτυρος ἑαυτοῦ· τοῖς μὲν γὰρ ἄλλοις ἅπασιν ὀχλαγωγὸς ἐδόκει πονηρὸς εἶναι καὶ τῷ βίῳ καὶ τῷ λόγῳ διεφθαρμένος, ὥστε εἰκότως ἐλεήσαι τις ἂν τὴν Ἀλεξάνδρειαν, εἴπερ ἐπὶ τούτῳ μέγα ἐφρόνει. περὶ δὲ τῶν παρʼ ἡμῖν ἀνδρῶν γεγονότων οὐδενὸς ἧττον ἐπαίνου τυγχάνειν ἀξίων ἴσασιν οἱ ταῖς ἡμετέραις ἀρχαιολογίαις ἐντυγχάνοντες."},{"number":137,"text":"Τὰ λοιπὰ τῶν ἐν τῇ κατηγορίᾳ γεγραμμένων ἄξιον ἦν ἴσως ἀναπολόγητα παραλιπεῖν, ἵνʼ αὐτὸς αὐτοῦ καὶ τῶν ἄλλων Αἰγυπτίων ᾖ ὁ κατηγορῶν· ἐγκαλεῖ γὰρ, ὅτι ζῷα θύομεν καὶ χοῖρον οὐκ ἐσθίομεν καὶ τὴν τῶν αἰδοίων χλευάζει περιτομήν."},{"number":138,"text":"τὸ μὲν οὖν περὶ τῆς τῶν ἡμέρων ζῴων ἀναιρέσεως κοινόν ἐστι καὶ πρὸς τοὺς ἄλλους ἀνθρώπους ἅπαντας, Ἀπίων δὲ τοῖς θύουσιν ἐγκαλῶν αὑτὸν ἐξήλεγξεν ὄντα τὸ γένος Αἰγύπτιον· οὐ γὰρ ἂν Ἕλλην ὢν ἢ Μακεδὼν ἐχαλέπαινεν· οὗτοι γὰρ εὔχονται θύειν ἑκατόμβας τοῖς θεοῖς καὶ χρῶνται τοῖς ἱερείοις πρὸς εὐωχίαν, καὶ οὐ διὰ τοῦτο συμβέβηκεν ἐρημοῦσθαι τὸν κόσμον τῶν βοσκημάτων, ὅπερ Ἀπίων ἔδεισεν."},{"number":139,"text":"εἰ μέντοι τοῖς Αἰγυπτίων ἔθεσιν ἠκολούθουν ἅπαντες, ἠρήμωτο μὲν ἂν ὁ κόσμος τῶν ἀνθρώπων, τῶν ἀγριωτάτων δὲ θηρίων ἐπληθύνθη, ἃ θεοὺς οὗτοι νομίζοντες ἐπιμελῶς ἐκτρέφουσιν."},{"number":140,"text":"καὶ μὴν εἴ τις αὐτὸν ἤρετο, τῶν πάντων Αἰγυπτίων τίνας εἶναι καὶ σοφωτάτους καὶ θεοσεβεῖς νομίζει, πάντως ἂν ὡμολόγησε τοὺς ἱερεῖς·"},{"number":141,"text":"δύο γὰρ αὐτούς φασιν ὑπὸ τῶν βασιλέων ἐξ ἀρχῆς ταῦτα προστετάχθαι, τὴν τῶν θεῶν θεραπείαν καὶ τῆς σοφίας τὴν ἐπιμέλειαν. ἐκεῖνοι τοίνυν ἅπαντες καὶ περιτέμνονται καὶ χοιρείων ἀπέχονται βρωμάτων, οὐ μὴν οὐδὲ τῶν ἄλλων Αἰγυπτίων οὐδὲ εἷς ὗν θύει τοῖς θεοῖς."},{"number":142,"text":"ἆρʼ οὖν τυφλὸς ἦν τὸν νοῦν Ἀπίων ὑπὲρ Αἰγυπτίων ἡμῖν λοιδορεῖν συνθέμενος, ἐκείνων δὲ κατηγορῶν, οἵ γε μὴ μόνον χρῶνται τοῖς ὑπὸ τούτου λοιδορουμένοις ἔθεσιν, ἀλλὰ καὶ τοὺς ἄλλους ἐδίδαξαν περιτέμνεσθαι, καθάπερ εἴρηκεν Ἡρόδοτος;"},{"number":143,"text":"ὅθεν εἰκότως μοι δοκεῖ τῆς εἰς τοὺς πατρίους αὐτοῦ νόμους βλασφημίας δοῦναι δίκην Ἀπίων τὴν πρέπουσαν· περιετμήθη γὰρ ἐξ ἀνάγκης ἑλκώσεως αὐτῷ περὶ τὸ αἰδοῖον γενομένης. καὶ μηδὲν ὠφεληθεὶς ὑπὸ τῆς περιτομῆς ἀλλὰ σηπόμενος ἐν δειναῖς ὀδύναις ἀπέθανεν."},{"number":144,"text":"δεῖ γὰρ τοὺς εὖ φρονοῦντας τοῖς μὲν οἰκείοις νόμοις περὶ τὴν εὐσέβειαν ἀκριβῶς ἐμμένειν, τοὺς δὲ τῶν ἄλλων μὴ λοιδορεῖν· ὁ δὲ τούτους μὲν ἔφυγεν, τῶν ἡμετέρων δὲ κατεψεύσατο. τοῦτο μὲν Ἀπίωνι τοῦ βίου τὸ τέλος ἐγένετο καὶ τοῦτο [παρʼ] ἡμῶν ἐνταῦθα τὸ πέρας ἔστω τοῦ λόγου."},{"number":145,"text":"Ἐπεὶ δὲ καὶ Ἀπολλώνιος ὁ Μόλων καὶ Λυσίμαχος καί τινες ἄλλοι τὰ μὲν ὑπʼ ἀγνοίας, τὸ πλεῖστον δὲ κατὰ δυσμένειαν περί τε τοῦ νομοθετήσαντος ἡμῖν Μωσέως καὶ περὶ τῶν νόμων πεποίηνται λόγους οὔτε δικαίους οὔτε ἀληθεῖς, τὸν μὲν ὡς γόητα καὶ ἀπατεῶνα διαβάλλοντες, τοὺς νόμους δὲ κακίας ἡμῖν καὶ οὐδεμιᾶς ἀρετῆς φάσκοντες εἶναι διδασκάλους, βούλομαι συντόμως καὶ περὶ τῆς ὅλης ἡμῶν καταστάσεως τοῦ πολιτεύματος καὶ περὶ τῶν κατὰ μέρος ὡς ἂν ὦ δυνατὸς εἰπεῖν."},{"number":146,"text":"οἶμαι γὰρ ἔσεσθαι φανερόν, ὅτι καὶ πρὸς εὐσέβειαν καὶ πρὸς κοινωνίαν τὴν μετʼ ἀλλήλων καὶ πρὸς τὴν καθόλου φιλανθρωπίαν ἔτι δὲ πρὸς δικαιοσύνην καὶ τὴν ἐν τοῖς πόνοις καρτερίαν καὶ θανάτου περιφρόνησιν ἄριστα κειμένους ἔχομεν τοὺς νόμους."},{"number":147,"text":"παρακαλῶ δὲ τοὺς ἐντευξομένους τῇ γραφῇ μὴ μετὰ φθόνου ποιεῖσθαι τὴν ἀνάγνωσιν· οὐ γὰρ ἐγκώμιον ἡμῶν αὐτῶν προειλόμην συγγράφειν, ἀλλὰ πολλὰ καὶ ψευδῆ κατηγορουμένοις ἡμῖν ταύτην ἀπολογίαν δικαιοτάτην εἶναι νομίζω τὴν ἀπὸ τῶν νόμων, καθʼ οὓς ζῶντες διατελοῦμεν."},{"number":148,"text":"ἄλλως τε καὶ τὴν κατηγορίαν ὁ Ἀπολλώνιος οὐκ ἀθρόαν ὥσπερ ὁ Ἀπίων ἔταξεν, ἀλλὰ σποράδην, καὶ δὴ εἴπας ποτὲ μὲν ὡς ἀθέους καὶ μισανθρώπους λοιδορεῖ, ποτὲ δʼ αὖ δειλίαν ἡμῖν ὀνειδίζει καὶ τοὔμπαλιν ἔστιν ὅπου τόλμαν κατηγορεῖ καὶ ἀπόνοιαν. λέγει δὲ καὶ ἀφυεστάτους εἶναι τῶν βαρβάρων καὶ διὰ τοῦτο μηδὲν εἰς τὸν βίον εὕρημα συμβεβλῆσθαι μόνους."},{"number":149,"text":"ταῦτα δὲ πάντα διελεγχθήσεσθαι νομίζω σαφῶς, εἰ τἀναντία τῶν εἰρημένων φανείη καὶ διὰ τῶν νόμων ἡμῖν προστεταγμένα καὶ πραττόμενα μετὰ πάσης ἀκριβείας ὑφʼ ἡμῶν."},{"number":150,"text":"εἰ δʼ ἄρα βιασθείην μνησθῆναι τῶν παρʼ ἑτέροις ὑπεναντίως νενομισμένων, τούτου δίκαιοι τὴν αἰτίαν ἔχειν εἰσὶν οἱ τὰ παρʼ ἡμῖν ὡς χείρω παραβάλλειν ἀξιοῦντες· οἷς οὐδέτερον ἀπολειφθήσεσθαι νομίζω λέγειν, οὔθʼ ὡς οὐχὶ τούτους ἔχομεν τοὺς νόμους, ὧν ἐγὼ παραθήσομαι τοὺς κεφαλαιωδεστάτους, οὔθʼ ὡς οὐχὶ μάλιστα πάντων ἐμμένομεν τοῖς ἑαυτῶν νόμοις."},{"number":151,"text":"Μικρὸν οὖν ἀναλαβὼν τὸν λόγον τοῦτʼ ἂν εἴποιμι πρῶτον, ὅτι τῶν ἀνόμως καὶ ἀτάκτως βιούντων οἱ τάξεως καὶ νόμου κοινωνίας ἐπιθυμηταὶ γενόμενοι καὶ πρῶτοι κατάρξαντες εἰκότως ἂν ἡμερότητι καὶ φύσεως ἀρετῇ διενεγκεῖν μαρτυρηθεῖεν."},{"number":152,"text":"ἀμέλει πειρῶνται τὰ παρʼ αὐτοῖς ἕκαστοι πρὸς τὸ ἀρχαιότατον ἀνάγειν, ἵνα μὴ μιμεῖσθαι δόξωσιν ἑτέρους, ἀλλʼ αὐτοὶ τοῦ ζῆν νομίμως ἄλλοις ὑφηγήσασθαι."},{"number":153,"text":"τούτων δὲ τοῦτον ἐχόντων τὸν τρόπον ἀρετὴ μέν ἐστι νομοθέτου τὰ βέλτιστα συνιδεῖν καὶ πεῖσαι τοὺς χρησομένους περὶ τῶν ὑπʼ αὐτοῦ τιθεμένων, πλήθους δὲ τὸ πᾶσι τοῖς δόξασιν ἐμμεῖναι καὶ μήτε εὐτυχίαις μήτε συμφοραῖς αὐτῶν μηδὲν μεταβάλλειν."},{"number":154,"text":"φημὶ τοίνυν τὸν ἡμέτερον νομοθέτην τῶν ὁπουδηποτοῦν μνημονευομένων νομοθετῶν προάγειν ἀρχαιότητι· Λυκοῦργοι γὰρ καὶ Σόλωνες καὶ Ζάλευκος ὁ τῶν Λοκρῶν καὶ πάντες οἱ θαυμαζόμενοι παρὰ τοῖς Ἕλλησιν ἐχθὲς δὴ καὶ πρῴην ὡς πρὸς ἐκεῖνον παραβαλλόμενοι φαίνονται γεγονότες, ὅπου γε μηδʼ αὐτὸ τοὔνομα πάλαι ἐγιγνώσκετο τοῦ νόμου παρὰ τοῖς Ἕλλησι."},{"number":155,"text":"καὶ μάρτυς Ὅμηρος οὐδαμοῦ τῆς ποιήσεως αὐτῷ χρησάμενος· οὐδὲ γὰρ ἦν κατὰ τοῦτον, ἀλλὰ γνώμαις ἀορίστοις τὰ πλήθη διῳκεῖτο καὶ προστάγμασι τῶν βασιλέων, ἀφʼ οὗ καὶ μέχρι πολλοῦ διέμειναν ἔθεσιν ἀγράφοις χρώμενοι καὶ πολλὰ τούτων ἀεὶ πρὸς τὸ συντυγχάνον μετατιθέντες."},{"number":156,"text":"ὁ δʼ ἡμέτερος νομοθέτης ἀρχαιότατος γεγονώς, τοῦτο γὰρ δήπουθεν ὁμολογεῖται καὶ παρὰ τοῖς πάντα καθʼ ἡμῶν λέγουσιν, ἑαυτόν τε παρέσχεν ἄριστον τοῖς πλήθεσιν ἡγεμόνα καὶ σύμβουλον τήν τε κατασκευὴν αὐτοῖς ὅλην τοῦ βίου τῷ νόμῳ περιλαβὼν ἔπεισεν παραδέξασθαι καὶ βεβαιοτάτην εἰς ἀεὶ φυλαχθῆναι παρεσκεύασεν."},{"number":157,"text":"Ἴδωμεν δὲ τῶν ἔργων αὐτοῦ τὸ πρῶτον μεγαλεῖον· ἐκεῖνος γὰρ τοὺς προγόνους ἡμῶν, ἐπείπερ ἔδοξεν αὐτοῖς τὴν Αἴγυπτον ἐκλιποῦσιν ἐπὶ τὴν πάτριον γῆν ἐπανιέναι, πολλὰς τὰς μυριάδας παραλαβὼν ἐκ πολλῶν καὶ ἀμηχάνων διέσωσεν εἰς ἀσφάλειαν· καὶ γὰρ τὴν ἄνυδρον αὐτοὺς καὶ πολλὴν ψάμμον ἔδει διοδοιπορῆσαι καὶ νικῆσαι πολεμίους καὶ τέκνα καὶ γυναῖκας καὶ λείαν ὁμοῦ σώζειν μαχομένους."},{"number":158,"text":"ἐν οἷς ἅπασι καὶ στρατηγὸς ἄριστος ἐγένετο καὶ σύμβουλος συνετώτατος καὶ πάντων κηδεμὼν ἀληθέστατος. ἅπαν δὲ τὸ πλῆθος εἰς ἑαυτὸν ἀνηρτῆσθαι παρεσκεύασεν, καὶ περὶ παντὸς ἔχων πεισθέντας [ἀντὶ τοῦ κελευσθέντος] εἰς οὐδεμίαν οἰκείαν ἔλαβεν ταῦτα πλεονεξίαν, ἀλλʼ ἐν ᾧ μάλιστα τοῦ καιροῦ δυνάμεις μὲν αὐτοῖς περιβάλλονται καὶ τυραννίδας οἱ προεστηκότες, ἐθίζουσι δὲ τὰ πλήθη μετὰ πολλῆς ζῆν ἀνομίας,"},{"number":159,"text":"ἐν τούτῳ τῆς ἐξουσίας ἐκεῖνος καθεστηκὼς τοὐναντίον ᾠήθη δεῖν εὐσεβεῖν καὶ πολλὴν εὔνοιαν τοῖς λαοῖς ἐμπαρασχεῖν, οὕτως αὐτός τε τὰ μάλιστα τὴν ἀρετὴν ἐπιδείξειν τὴν αὐτοῦ νομίζων καὶ σωτηρίαν τοῖς αὐτὸν ἡγεμόνα πεποιημένοις βεβαιοτάτην παρέξειν."},{"number":160,"text":"καλῆς οὖν αὐτῷ προαιρέσεως καὶ πράξεων μεγάλων ἐπιτυγχανομένων εἰκότως ἐνόμιζεν ἡγεμόνα τε καὶ σύμβουλον θεὸν ἔχειν, καὶ πείσας πρότερον ἑαυτὸν ὅτι κατὰ τὴν ἐκείνου βούλησιν ἅπαντα πράττει καὶ διανοεῖται, ταύτην ᾤετο δεῖν πρὸ παντὸς ἐμποιῆσαι τὴν ὑπόληψιν τοῖς πλήθεσιν· οἱ γὰρ πιστεύσαντες ἐπισκοπεῖν θεὸν τοὺς ἑαυτῶν βίους οὐθὲν ἀνέχονται ἐξαμαρτεῖν."},{"number":161,"text":"τοιοῦτος μὲν δή τις [αὐτὸς] ἡμῶν ὁ νομοθέτης, οὐ γόης οὐδʼ ἀπατεών, ἅπερ λοιδοροῦντες λέγουσιν ἀδίκως, ἀλλʼ οἵους παρὰ τοῖς Ἕλλησιν αὐχοῦσιν τὸν Μίνω γεγονέναι καὶ μετὰ ταῦτα τοὺς ἄλλους νομοθέτας·"},{"number":162,"text":"οἱ μὲν γὰρ αὐτῶν τοὺς νόμους ὑποτίθενται, ὁ δέ γε Μίνως ἔλεγεν ὅτι εἰς τὸν Ἀπόλλω καὶ τὸ Δελφικὸν αὐτοῦ μαντεῖον τὰς τῶν νόμων μαντείας ἀνέφερεν, ἤτοι τἀληθὲς οὕτως ἔχειν νομίζοντες ἢ πείσειν ῥᾷον ὑπολαμβάνοντες."},{"number":163,"text":"τίς δʼ ἦν ὁ μάλιστα κατορθώσας τοὺς νόμους καὶ τῆς δικαιοτάτης περὶ θεοῦ πίστεως ἐπιτυχών, πάρεστιν ἐξ αὐτῶν κατανοεῖν τῶν νόμων ἀντιπαραβάλλοντας· ἤδη γὰρ περὶ τούτων λεκτέον."},{"number":164,"text":"οὐκοῦν ἄπειροι μὲν αἱ κατὰ μέρος τῶν ἐθῶν καὶ τῶν νόμων παρὰ τοῖς ἅπασιν ἀνθρώποις διαφοραί, κεφαλαιωδῶς ἂν ἐπίοι τις· οἱ μὲν γὰρ μοναρχίαις, οἱ δὲ ταῖς ὀλίγων δυναστείαις, ἄλλοι δὲ τοῖς πλήθεσιν ἐπέτρεψαν τὴν ἐξουσίαν τῶν πολιτευμάτων."},{"number":165,"text":"ὁ δʼ ἡμέτερος νομοθέτης εἰς μὲν τούτων οὐδοτιοῦν ἀπεῖδεν, ὡς δʼ ἄν τις εἴποι βιασάμενος τὸν λόγον θεοκρατίαν ἀπέδειξε τὸ πολίτευμα θεῷ τὴν ἀρχὴν καὶ τὸ κράτος ἀναθείς."},{"number":166,"text":"καὶ πείσας εἰς ἐκεῖνον ἅπαντας ἀφορᾶν ὡς αἴτιον μὲν ἁπάντων ὄντα τῶν ἀγαθῶν, ἃ κοινῇ τε πᾶσιν ἀνθρώποις ὑπάρχει καὶ ὅσων ἔτυχον αὐτοὶ δεηθέντες ἐν ἀμηχάνοις, λαθεῖν δὲ τὴν ἐκείνου γνώμην οὐκ ἐνὸν οὔτε τῶν πραττομένων οὐδὲν οὔθʼ ὧν ἄν τις παρʼ αὐτῷ διανοηθῇ,"},{"number":167,"text":"ἕνα αὐτὸν ἀπέφηνε καὶ ἀγένητον καὶ πρὸς τὸν ἀίδιον χρόνον ἀναλλοίωτον πάσης ἰδέας θνητῆς κάλλει διαφέροντα καὶ δυνάμει μὲν ἡμῖν γνώριμον, ὁποῖος δὲ κατʼ οὐσίαν [ἐστὶν] ἄγνωστον."},{"number":168,"text":"ταῦτα περὶ θεοῦ φρονεῖν οἱ σοφώτατοι παρʼ Ἕλλησιν ὅτι μὲν ἐδιδάχθησαν ἐκείνου τὰς ἀρχὰς παρασχόντος, ἐῶ νῦν λέγειν, ὅτι δʼ ἐστὶ καλὰ καὶ πρέποντα τῇ τοῦ θεοῦ φύσει καὶ μεγαλειότητι, σφόδρα μεμαρτυρήκασι· καὶ γὰρ Πυθαγόρας καὶ Ἀναξαγόρας καὶ Πλάτων οἵ τε μετʼ ἐκεῖνον ἀπὸ τῆς στοᾶς φιλόσοφοι καὶ μικροῦ δεῖν ἅπαντες οὕτως φαίνονται περὶ τῆς τοῦ θεοῦ φύσεως πεφρονηκότες."},{"number":169,"text":"ἀλλʼ οἱ μὲν πρὸς ὀλίγους φιλοσοφοῦντες εἰς πλήθη δόξαις προκατειλημμένα τὴν ἀλήθειαν τοῦ δόγματος ἐξενεγκεῖν οὐκ ἐτόλμησαν, ὁ δὲ ἡμέτερος νομοθέτης ἅτε δὴ τὰ ἔργα παρέχων σύμφωνα τοῖς λόγοις οὐ μόνον τοὺς καθʼ αὑτὸν ἔπεισεν, ἀλλὰ καὶ τοῖς ἐξ ἐκείνων ἀεὶ γενησομένοις τὴν περὶ θεοῦ πίστιν ἐνέφυσεν ἀμετακίνητον."},{"number":170,"text":"αἴτιον δʼ ὅτι καὶ τῷ τρόπῳ τῆς νομοθεσίας πρὸς τὸ χρήσιμον πάντων ἀεὶ πολὺ διήνεγκεν· οὐ γὰρ μέρος ἀρετῆς ἐποίησεν τὴν εὐσέβειαν, ἀλλὰ ταύτης μέρη τἆλλα, λέγω δὲ τὴν δικαιοσύνην τὴν σωφροσύνην τὴν καρτερίαν τὴν τῶν πολιτῶν πρὸς ἀλλήλους ἐν ἅπασι συμφωνίαν·"},{"number":171,"text":"ἅπασαι γὰρ αἱ πράξεις καὶ διατριβαὶ καὶ λόγοι πάντες ἐπὶ τὴν πρὸς θεὸν ἡμῖν εὐσέβειαν ἀναφέρουσιν· οὐδὲν γὰρ τούτων ἀνεξέταστον οὐδὲ ἀόριστον παρέλιπεν. δύο μὲν γάρ εἰσιν ἁπάσης παιδείας τρόποι καὶ τῆς περὶ τὰ ἤθη κατασκευῆς, ὧν ὁ μὲν λόγῳ διδασκαλικός, ὁ δὲ διὰ τῆς ἀσκήσεως τῶν ἠθῶν."},{"number":172,"text":"οἱ μὲν οὖν ἄλλοι νομοθέται ταῖς γνώμαις διέστησαν καὶ τὸν ἕτερον αὐτῶν ὃν ἔδοξεν ἑκάστοις ἑλόμενοι τὸν ἕτερον παρέλιπον, οἷον Λακεδαιμόνιοι μὲν καὶ Κρῆτες ἔθεσιν ἐπαίδευον, οὐ λόγοις, Ἀθηναῖοι δὲ καὶ σχεδὸν οἱ ἄλλοι πάντες Ἕλληνες ἃ μὲν χρὴ πράττειν ἢ μὴ προσέτασσον διὰ τῶν νόμων, τοῦ δὲ πρὸς αὐτὰ διὰ τῶν ἔργων ἐθίζειν ὠλιγώρουν."},{"number":173,"text":"Ὁ δʼ ἡμέτερος νομοθέτης ἄμφω ταῦτα συνήρμοσεν κατὰ πολλὴν ἐπιμέλειαν· οὔτε γὰρ κωφὴν ἀπέλιπε τὴν τῶν ἠθῶν ἄσκησιν οὔτε τὸν ἐκ τοῦ νόμου λόγον ἄπρακτον εἴασεν, ἀλλʼ εὐθὺς ἀπὸ τῆς πρώτης ἀρξάμενος τροφῆς καὶ τῆς κατὰ τὸν οἶκον ἑκάστων διαίτης οὐδὲν οὐδὲ τῶν βραχυτάτων αὐτεξούσιον ἐπὶ ταῖς βουλήσεσι τῶν χρησομένων κατέλιπεν,"},{"number":174,"text":"ἀλλὰ καὶ περὶ σιτίων, ὅσων ἀπέχεσθαι χρὴ καὶ τίνα προσφέρεσθαι, καὶ περὶ τῶν κοινωνησόντων τῆς διαίτης ἔργων τε συντονίας καὶ τοὔμπαλιν ἀναπαύσεως ὅρον ἔθηκεν αὐτὸς καὶ κανόνα τὸν νόμον, ἵνʼ ὥσπερ ὑπὸ πατρὶ τούτῳ καὶ δεσπότῃ ζῶντες μήτε βουλόμενοι μηθὲν μήθʼ ὑπʼ ἀγνοίας ἁμαρτάνωμεν."},{"number":175,"text":"οὐδὲ γὰρ τὴν ἀπὸ τῆς ἀγνοίας ὑποτίμησιν κατέλιπεν, ἀλλὰ καὶ κάλλιστον καὶ ἀναγκαιότατον ἀπέδειξε παίδευμα τὸν νόμον, οὐκ εἰσάπαξ ἀκροασομένοις οὐδὲ δὶς ἢ πολλάκις, ἀλλʼ ἑκάστης ἑβδομάδος τῶν ἄλλων ἔργων ἀφεμένους ἐπὶ τὴν ἀκρόασιν ἐκέλευσε τοῦ νόμου συλλέγεσθαι καὶ τοῦτον ἀκριβῶς ἐκμανθάνειν· ὃ δὴ πάντες ἐοίκασιν οἱ νομοθέται παραλιπεῖν."},{"number":176,"text":"Καὶ τοσοῦτον οἱ πλεῖστοι τῶν ἀνθρώπων ἀπέχουσι τοῦ κατὰ τοὺς οἰκείους νόμους ζῆν, ὥστε σχεδὸν αὐτοὺς οὐδʼ ἴσασιν, ἀλλʼ ὅταν ἐξαμάρτωσιν, τότε παρʼ ἄλλων μανθάνουσιν, ὅτι τὸν νόμον παραβεβήκασιν,"},{"number":177,"text":"οἵ τε τὰς μεγίστας καὶ κυριωτάτας παρʼ αὐτοῖς ἀρχὰς διοικοῦντες ὁμολογοῦσι τὴν ἄγνοιαν· ἐπιστάτας γὰρ παρακαθίστανται τῆς τῶν πραγμάτων οἰκονομίας τοὺς ἐμπειρίαν ἔχειν τῶν νόμων ὑπισχνουμένους."},{"number":178,"text":"ἡμῶν δὲ ὁντινοῦν τις ἔροιτο τοὺς νόμους ῥᾷον ἂν εἴποι πάντας ἢ τοὔνομα τὸ ἑαυτοῦ. τοιγαροῦν ἀπὸ τῆς πρώτης εὐθὺς αἰσθήσεως αὐτοὺς ἐκμανθάνοντες ἔχομεν ἐν ταῖς ψυχαῖς ὥσπερ ἐγκεχαραγμένους, καὶ σπάνιος μὲν ὁ παραβαίνων, ἀδύνατος δʼ ἡ τῆς κολάσεως παραίτησις."},{"number":179,"text":"Τοῦτο πρῶτον ἁπάντων τὴν θαυμαστὴν ὁμόνοιαν ἡμῖν ἐμπεποίηκεν· τὸ γὰρ μίαν μὲν ἔχειν καὶ τὴν αὐτὴν δόξαν περὶ θεοῦ, τῷ βίῳ δὲ καὶ τοῖς ἔθεσι μηδὲν ἀλλήλων διαφέρειν, καλλίστην ἐν ἤθεσιν ἀνθρώπων συμφωνίαν ἀποτελεῖ."},{"number":180,"text":"παρʼ ἡμῖν γὰρ μόνοις οὔτε περὶ θεοῦ λόγους ἀκούσεταί τις ἀλλήλοις ὑπεναντίους, ὁποῖα πολλὰ παρʼ ἑτέροις οὐχ ὑπὸ τῶν τυχόντων μόνον κατὰ τὸ προσπεσὸν ἑκάστῳ λέγεται πάθος, ἀλλὰ καὶ παρά τισι τῶν φιλοσόφων ἀποτετόλμηται, τῶν μὲν τὴν ὅλην τοῦ θεοῦ φύσιν ἀναιρεῖν τοῖς λόγοις ἐπικεχειρηκότων, ἄλλων δὲ τὴν ὑπὲρ ἀνθρώπων αὐτὸν πρόνοιαν ἀφαιρουμένων·"},{"number":181,"text":"οὔτʼ ἐν τοῖς ἐπιτηδεύμασι τῶν βίων ὄψεται διαφοράν, ἀλλὰ κοινὰ μὲν ἔργα πάντων παρʼ ἡμῖν, εἷς δὲ λόγος ὁ τῷ νόμῳ συμφωνῶν περὶ θεοῦ πάντα λέγων ἐκεῖνον ἐφορᾶν. καὶ μὴν περὶ τῶν κατὰ τὸν βίον ἐπιτηδευμάτων, ὅτι δεῖ πάντα τἆλλα τέλος ἔχειν τὴν εὐσέβειαν, καὶ γυναικῶν ἀκούσειεν ἄν τις καὶ τῶν οἰκετῶν."},{"number":182,"text":"Ὅθεν δὴ καὶ τὸ προφερόμενον ἡμῖν ὑπό τινων ἔγκλημα, τὸ δὴ μὴ καινῶν εὑρετὰς ἔργων ἢ λόγων ἄνδρας παρασχεῖν, ἐντεῦθεν συμβέβηκεν· οἱ μὲν γὰρ ἄλλοι τὸ μηδενὶ τῶν πατρίων ἐμμένειν καλὸν εἶναι νομίζουσι καὶ τοῖς τολμῶσι ταῦτα παραβαίνειν μάλιστα σοφίας δεινότητα μαρτυροῦσιν,"},{"number":183,"text":"ἡμεῖς δὲ τοὐναντίον μίαν εἶναι καὶ φρόνησιν καὶ ἀρετὴν ὑπειλήφαμεν τὸ μηδὲν ὅλως ὑπεναντίον μήτε πρᾶξαι μήτε διανοηθῆναι τοῖς ἐξ ἀρχῆς νομοθετηθεῖσιν. ὅπερ εἰκότως ἂν εἴη τεκμήριον τοῦ κάλλιστα τὸν νόμον τεθῆναι· τὰ γὰρ μὴ τοῦτον ἔχοντα τὸν τρόπον αἱ πεῖραι δεόμενα διορθώσεως ἐλέγχουσιν."},{"number":184,"text":"Ἡμῖν δὲ τοῖς πεισθεῖσιν ἐξ ἀρχῆς τεθῆναι τὸν νόμον κατὰ θεοῦ βούλησιν οὐδʼ εὐσεβὲς ἦν τοῦτον μὴ φυλάττειν· τί γὰρ αὐτοῦ τις ἂν μετακινήσειεν ἢ τί κάλλιον ἐξεῦρεν ἢ τί παρʼ ἑτέρων ὡς ἄμεινον μετήνεγκεν; ἆρά γε τὴν ὅλην κατάστασιν τοῦ πολιτεύματος;"},{"number":185,"text":"καὶ τίς ἂν καλλίων ἢ δικαιοτέρα γένοιτο τῆς θεὸν μὲν ἡγεμόνα τῶν ὅλων πεποιημένης, τοῖς ἱερεῦσι δὲ κοινῇ μὲν τὰ μέγιστα διοικεῖν ἐπιτρεπούσης, τῷ δὲ πάντων ἀρχιερεῖ πάλιν αὖ πεπιστευκυίας τὴν τῶν ἄλλων ἱερέων ἡγεμονίαν;"},{"number":186,"text":"οὓς οὐ κατὰ πλοῦτον οὐδέ τισιν ἄλλαις προύχοντας αὐτομάτοις πλεονεξίαις τὸ πρῶτον εὐθὺς ὁ νομοθέτης ἐπὶ τὴν τιμὴν ἔταξεν, ἀλλʼ ὅσοι τῶν μετʼ αὐτοῦ πειθοῖ τε καὶ σωφροσύνῃ τῶν ἄλλων διέφερον, τούτοις τὴν περὶ τὸν θεὸν μάλιστα θεραπείαν ἐνεχείρισεν."},{"number":187,"text":"τοῦτο δʼ ἦν καὶ τοῦ νόμου καὶ τῶν ἄλλων ἐπιτηδευμάτων ἀκριβὴς ἐπιμέλεια· καὶ γὰρ ἐπόπται πάντων καὶ δικασταὶ τῶν ἀμφισβητουμένων καὶ κολασταὶ τῶν κατεγνωσμένων οἱ ἱερεῖς ἐτάχθησαν."},{"number":188,"text":"Τίς ἂν οὖν ἀρχὴ γένοιτο ταύτης ὁσιωτέρα; τίς δὲ τιμὴ θεῷ μᾶλλον ἁρμόζουσα, παντὸς μὲν τοῦ πλήθους κατεσκευασμένου πρὸς τὴν εὐσέβειαν, ἐξαίρετον δὲ τὴν ἐπιμέλειαν τῶν ἱερέων πεπιστευμένων, ὥσπερ δὲ τελετῆς τινος τῆς ὅλης πολιτείας οἰκονομουμένης;"},{"number":189,"text":"ἃ γὰρ ὀλίγων ἡμερῶν ἀριθμὸν ἐπιτηδεύοντες ἄλλοι φυλάττειν οὐ δύνανται μυστήρια καὶ τελετὰς ἐπονομάζοντες, ταῦτα μεθʼ ἡδονῆς καὶ γνώμης ἀμεταθέτου φυλάττομεν ἡμεῖς διʼ αἰῶνος."},{"number":190,"text":"τίνες οὖν εἰσιν αἱ προρρήσεις καὶ ἀπαγορεύσεις; ἁπλαῖ τε καὶ γνώριμοι. πρώτη δʼ ἡγεῖται ἡ περὶ θεοῦ λέγουσα, ὁ θεὸς ἔχει τὰ σύμπαντα παντελὴς καὶ μακάριος, αὐτὸς αὑτῷ καὶ πᾶσιν αὐτάρκης, ἀρχὴ καὶ μέσα καὶ τέλος οὗτος τῶν πάντων, ἔργοις μὲν καὶ χάρισιν ἐναργὴς καὶ παντὸς οὗτινος φανερώτερος, μορφὴν δὲ καὶ μέγεθος ἡμῖν ἄφατος·"},{"number":191,"text":"πᾶσα μὲν ὕλη πρὸς εἰκόνα τὴν τούτου κἂν ᾖ πολυτελὴς ἄτιμος, πᾶσα δὲ τέχνη πρὸς μιμήσεως ἐπίνοιαν ἄτεχνος. οὐδὲν ὅμοιον οὔτʼ εἴδομεν οὔτʼ ἐπινοοῦμεν οὔτʼ εἰκάζειν ἐστὶν ὅσιον."},{"number":192,"text":"ἔργα βλέπομεν αὐτοῦ φῶς οὐρανὸν γῆν ἥλιον ὕδατα ζῴων γενέσεις καρπῶν ἀναδόσεις. ταῦτα θεὸς ἐποίησεν οὐ χερσὶν οὐ πόνοις οὔ τινων συνεργασομένων ἐπιδεηθείς, ἀλλʼ αὐτοῦ θελήσαντος καλῶς ἦν εὐθὺς γεγονότα. τοῦτον θεραπευτέον ἀσκοῦντας ἀρετήν· τρόπος γὰρ θεοῦ θεραπείας οὗτος ὁσιώτατος."},{"number":193,"text":"Εἷς ναὸς ἑνὸς θεοῦ, φίλον γὰρ ἀεὶ παντὶ τὸ ὅμοιον, κοινὸς ἁπάντων κοινοῦ θεοῦ ἁπάντων. τοῦτον θεραπεύσουσιν μὲν διὰ παντὸς οἱ ἱερεῖς, ἡγήσεται δὲ τούτων ὁ πρῶτος ἀεὶ κατὰ γένος."},{"number":194,"text":"οὗτος μετὰ τῶν συνιερέων θύσει τῷ θεῷ, φυλάξει τοὺς νόμους, δικάσει περὶ τῶν ἀμφισβητουμένων, κολάσει τοὺς ἐλεγχθέντας. ὁ τούτῳ μὴ πειθόμενος ὑφέξει δίκην ὡς εἰς θεὸν αὐτὸν ἀσεβῶν."},{"number":195,"text":"θύομεν τὰς θυσίας οὐκ εἰς μέθην ἑαυτοῖς, ἀβούλητον γὰρ θεῷ τόδε, ἀλλʼ εἰς σωφροσύνην."},{"number":196,"text":"καὶ ἐπὶ ταῖς θυσίαις χρὴ πρῶτον ὑπὲρ τῆς κοινῆς εὔχεσθαι σωτηρίας, εἶθʼ ὑπὲρ ἑαυτῶν· ἐπὶ γὰρ κοινωνίᾳ γεγόναμεν καὶ ταύτην ὁ προτιμῶν τοῦ καθʼ αὑτὸν ἰδίου μάλιστα θεῷ κεχαρισμένος."},{"number":197,"text":"δέησις δʼ ἔστω πρὸς τὸν θεόν, οὐχ ὅπως δῷ τἀγαθά, δέδωκεν γὰρ αὐτὸς ἑκὼν καὶ πᾶσιν εἰς μέσον κατατέθεικεν, ἀλλʼ ὅπως δέχεσθαι δυνώμεθα καὶ λαβόντες φυλάττωμεν."},{"number":198,"text":"ἁγνείας ἐπὶ ταῖς θυσίαις διείρηκεν ὁ νόμος ἀπὸ κήδους ἀπὸ λέχους ἀπὸ κοινωνίας τῆς πρὸς γυναῖκα καὶ πολλῶν ἄλλων. [ἃ μακρὸν ἂν εἴη γράφειν. τοιοῦτος μὲν ὁ περὶ θεοῦ καὶ τῆς ἐκείνου θεραπείας λόγος ἡμῖν ἐστιν, ὁ δʼ αὐτὸς ἅμα καὶ νόμος.]"},{"number":199,"text":"Τίνες δʼ οἱ περὶ γάμων νόμοι; μῖξιν μόνην οἶδεν ὁ νόμος τὴν κατὰ φύσιν τὴν πρὸς γυναῖκα καὶ ταύτην, εἰ μέλλοι τέκνων ἕνεκα γίνεσθαι. τὴν δὲ πρὸς ἄρρενας ἀρρένων ἐστύγηκεν καὶ θάνατος τοὐπιτίμιον, εἴ τις ἐπιχειρήσειεν."},{"number":200,"text":"γαμεῖν δὲ κελεύει μὴ προικὶ προσέχοντας μηδὲ βιαίοις ἁρπαγαῖς μηδʼ αὖ δόλῳ καὶ ἀπάτῃ πείσαντας, ἀλλὰ μνηστεύειν παρὰ τοῦ δοῦναι κυρίου καὶ κατὰ συγγένειαν ἐπιτηδείου."},{"number":201,"text":"γυνὴ χείρων, φησίν, ἀνδρὸς εἰς ἅπαντα. τοιγαροῦν ὑπακουέτω, μὴ πρὸς ὕβριν, ἀλλʼ ἵνʼ ἄρχηται· θεὸς γὰρ ἀνδρὶ τὸ κράτος ἔδωκεν. ταύτῃ συνεῖναι δεῖ τὸν γήμαντα μόνῃ, τὸ δὲ τὴν ἄλλου πειρᾶν ἀνόσιον. εἰ δέ τις τοῦτο πράξειεν, οὐδεμία θανάτου παραίτησις, οὔτʼ εἰ βιάσαιτο παρθένον ἑτέρῳ προωμολογημένην, οὔτʼ εἰ πείσειεν γεγαμημένην."},{"number":202,"text":"τέκνα τρέφειν ἅπαντα προσέταξεν, καὶ γυναιξὶν ἀπεῖπεν μήτʼ ἀμβλοῦν τὸ σπαρὲν μήτε διαφθείρειν ἀλλὰ ἢν φανείη τεκνοκτόνος ἂν εἴη ψυχὴν ἀφανίζουσα καὶ τὸ γένος ἐλαττοῦσα. τοιγαροῦν οὐδʼ εἴ τις ἐπὶ λέχους φθορὰν παρέλθοι, καθαρὸς εἶναι τότε προσήκει."},{"number":203,"text":"καὶ μετὰ τὴν νόμιμον συνουσίαν ἀνδρὸς καὶ γυναικὸς ἀπολούσασθαι· ψυχῆς γὰρ ἔχειν τοῦτο μερισμὸν πρὸς ἄλλην χώραν ὑπέλαβεν· καὶ γὰρ ἐμφυομένη σώμασιν κακοπαθεῖ καὶ τούτων αὖ θανάτῳ διακριθεῖσα. διόπερ ἁγνείας ἐπὶ πᾶσι τοῖς τοιούτοις ἔταξεν."},{"number":204,"text":"Οὐ μὴν οὐδʼ ἐπὶ ταῖς τῶν παίδων γενέσεσιν ἐπέτρεψεν εὐωχίας συντελεῖν καὶ προφάσεις ποιεῖσθαι μέθης, ἀλλὰ σώφρονα τὴν ἀρχὴν εὐθὺς τῆς τροφῆς ἔταξε. καὶ γράμματα παιδεύειν ἐκέλευσεν τὰ περὶ τοὺς νόμους καὶ τῶν προγόνων τὰς πράξεις ἐπίστασθαι, τὰς μὲν ἵνα μιμῶνται, τοῖς δʼ ἵνα συντρεφόμενοι μήτε παραβαίνωσι μήτε σκῆψιν ἀγνοίας ἔχωσι."},{"number":205,"text":"Τῆς εἰς τοὺς τετελευτηκότας προυνόησεν ὁσίας οὐ πολυτελείαις ἐνταφίων οὐ κατασκευαῖς μνημείων ἐπιφανῶν, ἀλλὰ τὰ μὲν περὶ τὴν κηδείαν τοῖς οἰκειοτάτοις ἐπιτελεῖν, πᾶσι δὲ τοῖς παριοῦσι καὶ προσελθεῖν καὶ συναποδύρασθαι. καθαίρειν δὲ καὶ τὸν οἶκον καὶ τοὺς ἐνοικοῦντας ἀπὸ κήδους, ἵνα πλεῖστον ἀπέχῃ τοῦ δοκεῖν καθαρὸς εἶναί τις φόνον ἐργασάμενος."},{"number":206,"text":"Γονέων τιμὴν μετὰ τὴν πρὸς θεὸν δευτέραν ἔταξεν καὶ τὸν οὐκ ἀμειβόμενον τὰς παρʼ αὐτῶν χάριτας ἀλλʼ εἰς ὁτιοῦν ἐλλείποντα λευσθησόμενον παραδίδωσι. καὶ παντὸς τοῦ πρεσβυτέρου τιμὴν ἔχειν τοὺς νέους φησίν, ἐπεὶ πρεσβύτατον ὁ θεός."},{"number":207,"text":"κρύπτειν οὐδὲν ἐᾷ πρὸς φίλους· οὐ γὰρ εἶναι φιλίαν τὴν μὴ πάντα πιστεύουσαν. κἂν συμβῇ τις ἔχθρα, τἀπόρρητα λέγειν κεκώλυκε. δικάζων εἰ δῶρα τις λάβοι, θάνατος ἡ ζημία. περιορῶν ἱκέτην βοηθεῖν ἐνὸν ὑπεύθυνος."},{"number":208,"text":"ὃ μὴ κατέθηκέν τις οὐκ ἀναιρήσεται, τῶν ἀλλοτρίων οὐδενὸς ἅψεται, τόκον οὐ λήψεται. [ταῦτα καὶ πολλὰ τούτοις ὅμοια τὴν πρὸς ἀλλήλους ἡμῶν συνέχει κοινωνίαν]"},{"number":209,"text":"Πῶς δὲ καὶ τῆς πρὸς ἀλλοφύλους ἐπιεικείας ἐφρόντισεν ὁ νομοθέτης, ἄξιον ἰδεῖν, [φανεῖται γὰρ ἄριστα πάντων προνοησάμενος] ὅπως μήτε τὰ οἰκεῖα διαφθείρωμεν μήτε φθονήσωμεν τοῖς μετέχειν τῶν ἡμετέρων προαιρουμένοις."},{"number":210,"text":"ὅσοι μὲν γὰρ θέλουσιν ὑπὸ τοὺς αὐτοὺς ἡμῖν νόμους ζῆν ὑπελθόντες δέχεται φιλοφρόνως, οὐ τῷ γένει μόνον, ἀλλὰ καὶ τῇ προαιρέσει τοῦ βίου νομίζων εἶναι τὴν οἰκειότητα. τοὺς δʼ ἐκ παρέργου προσιόντας ἀναμίγνυσθαι τῇ συνηθείᾳ οὐκ ἠθέλησεν."},{"number":211,"text":"Τἆλλα δὲ προείρηκεν, ὧν ἡ μετάδοσίς ἐστιν ἀναγκαία· πᾶσι παρέχειν τοῖς δεομένοις πῦρ ὕδωρ τροφήν, ὁδοὺς φράζειν, ἄταφον μὴ περιορᾶν, ἐπιεικεῖς δὲ καὶ τὰ πρὸς τοὺς πολεμίους κριθέντας εἶναι·"},{"number":212,"text":"οὐ γὰρ ἐᾷ τὴν γῆν αὐτῶν πυρπολεῖν οὐδὲ τέμνειν ἥμερα δένδρα, ἀλλὰ καὶ σκυλεύειν ἀπείρηκεν τοὺς ἐν τῇ μάχῃ πεσόντας, καὶ τῶν αἰχμαλώτων προυνόησεν, ὅπως αὐτῶν ὕβρις ἀπῇ, μάλιστα δὲ γυναικῶν."},{"number":213,"text":"οὕτως δʼ ἡμερότητα καὶ φιλανθρωπίαν ἡμᾶς ἐξεπαίδευσεν, ὡς μηδὲ τῶν ἀλόγων ζῴων ὀλιγωρεῖν, ἀλλὰ μόνην ἐφῆκε τούτων χρῆσιν τὴν νόμιμον, πᾶσαν δʼ ἑτέραν ἐκώλυσεν· ἃ δʼ ὥσπερ ἱκετεύοντα προσφεύγει ταῖς οἰκίαις ἀπεῖπεν ἀνελεῖν. οὐδὲ νεοττοῖς τοὺς γονέας αὐτῶν ἐπέτρεψε συνεξαιρεῖν, φείδεσθαι δὲ κἀν τῇ πολεμίᾳ τῶν ἐργαζομένων ζῴων καὶ μὴ φονεύειν."},{"number":214,"text":"οὕτως πανταχόθεν τὰ πρὸς ἐπιείκειαν περιεσκέψατο, διδασκαλικοῖς μὲν τοῖς προειρημένοις χρησάμενος νόμοις, τοὺς δʼ αὖ κατὰ τῶν παραβαινόντων τιμωρητικοὺς τάξας ἄνευ προφάσεως."},{"number":215,"text":"Ζημία γὰρ ἐπὶ τοῖς πλείστοις τῶν παραβαινόντων ὁ θάνατος, ἂν μοιχεύσῃ τις, ἂν βιάσηται κόρην, ἂν ἄρρενι τολμήσῃ πεῖραν προσφέρειν, ἂν ὑπομείνῃ παθεῖν ὁ πειρασθείς. ἔστι δὲ καὶ ἐπὶ δούλοις ὁμοίως ὁ νόμος ἀπαραίτητος."},{"number":216,"text":"ἀλλὰ καὶ περὶ μέτρων ἤν τις κακουργήσῃ ἢ σταθμῶν ἢ περὶ πράσεως ἀδίκου καὶ δόλῳ γενομένης, κἂν ὑφέληταί τις ἀλλότριον, κἂν ὃ μὴ κατέθηκεν ἀνέληται, πάντων εἰσὶ κολάσεις οὐχ οἷαι παρʼ ἑτέροις, ἀλλʼ ἐπὶ τὸ μεῖζον."},{"number":217,"text":"περὶ μὲν γὰρ γονέων ἀδικίας ἢ τῆς εἰς θεὸν ἀσεβείας κἂν μελλήσῃ τις, εὐθὺς ἀπόλλυται. τοῖς μέντοι γε νομίμως βιοῦσι γέρας ἐστὶν οὐκ ἄργυρος οὐδὲ χρυσὸς οὐ κοτίνου στέφανος ἢ σελίνου καὶ τοιαύτη τις ἀνακήρυξις,"},{"number":218,"text":"ἀλλʼ αὐτὸς ἕκαστος αὑτῷ τὸ συνειδὸς ἔχων μαρτυροῦν πεπίστευκεν, τοῦ μὲν νομοθέτου προφητεύσαντος, τοῦ δὲ θεοῦ τὴν πίστιν ἰσχυρὰν παρεσχηκότος, ὅτι τοῖς τοὺς νόμους διαφυλάξασι κἂν εἰ δέοι θνήσκειν ὑπὲρ αὐτῶν προθύμως ἀποθανεῖν ἔδωκεν ὁ θεὸς γενέσθαι τε πάλιν καὶ βίον ἀμείνω λαβεῖν ἐκ περιτροπῆς."},{"number":219,"text":"ὤκνουν δʼ ἂν ἐγὼ ταῦτα γράφειν, εἰ μὴ διὰ τῶν ἔργων ἅπασιν ἦν φανερόν, ὅτι πολλοὶ καὶ πολλάκις ἤδη τῶν ἡμετέρων περὶ τοῦ μηδὲ ῥῆμα φθέγξασθαι παρὰ τὸν νόμον πάντα παθεῖν γενναίως προείλοντο."},{"number":220,"text":"[Κἂν τε τι μὴ συμβεβήκει γνώριμον ἡμῶν τὸ ἔθνος ἅπασιν ἀνθρώποις ὑπάρχει κἀν φανερῷ κεῖσθαι τὴν ἐθελούσιον ἡμῶν τοῖς νόμοις ἀκολουθίαν,]"},{"number":221,"text":"ἀλλά τις ἢ συγγράψαι λόγος αὐτοῖς ἀνεγίνωσκε τοῖς Ἕλλησιν ἤ που περιτυχεῖν ἔξω τῆς γινωσκομένης γῆς ἔφασκεν ἀνθρώποις τοιαύτην μὲν ἔχουσι δόξαν οὕτω σεμνὴν περὶ θεοῦ, τοιούτοις δὲ νόμοις πολὺν αἰῶνα βεβαίως ἐμμεμενηκόσι, πάντας ἂν οἶμαι θαυμάσαι διὰ τὰς συνεχεῖς παρʼ αὐτοῖς μεταβολάς."},{"number":222,"text":"ἀμέλει τῶν γράψαι τι παραπλήσιον εἰς πολιτείαν καὶ νόμους ἐπιχειρησάντων ὡς θαυμαστὰ συνθέντων κατηγοροῦσι, φάσκοντες αὐτοὺς λαβεῖν ἀδυνάτους ὑποθέσεις. καὶ τοὺς μὲν ἄλλους παραλείπω φιλοσόφους, ὅσοι τι τοιοῦτον ἐν τοῖς γράμμασιν ἐπραγματεύσαντο,"},{"number":223,"text":"Πλάτων δὲ θαυμαζόμενος παρὰ τοῖς Ἕλλησιν ὡς καὶ σεμνότητι βίου διενεγκὼν καὶ δυνάμει λόγων καὶ πειθοῖ πάντας ὑπεράρας τοὺς ἐν φιλοσοφίᾳ γεγονότας, ὑπὸ τῶν φασκόντων δεινῶν εἶναι τὰ πολιτικὰ μικροῦ δεῖν χλευαζόμενος καὶ κωμῳδούμενος διατελεῖ."},{"number":224,"text":"καίτοι τἀκείνου σκοπῶν συχνῶς τις ἂν εὕροι ῥᾷον καὶ ταῖς τῶν πολλῶν ἔγγιον συνηθείαις, αὐτὸς δὲ Πλάτων ὡμολόγηκεν, ὅτι τὴν ἀληθῆ περὶ θεοῦ δόξαν εἰς τὴν τῶν ὄχλων ἄνοιαν οὐκ ἦν ἀσφαλὲς ἐξενεγκεῖν."},{"number":225,"text":"ἀλλὰ τὰ μὲν Πλάτωνος λόγους τινὲς εἶναι κενοὺς νομίζουσι κατὰ πολλὴν ἐξουσίαν κεκαλλιγραφημένους, μάλιστα δὲ τῶν νομοθετῶν Λυκοῦργον τεθαυμάκασι καὶ τὴν Σπάρτην ἅπαντες ὑμνοῦσιν, ὅτι τοῖς ἐκείνου νόμοις ἐπὶ πλεῖστον ἐνεκαρτέρησαν."},{"number":226,"text":"οὐκοῦν τοῦτο μὲν ὡμολογήσθω τεκμήριον ἀρετῆς εἶναι τὸ πείθεσθαι τοῖς νόμοις· οἱ δὲ Λακεδαιμονίους θαυμάζοντες τὸν ἐκείνων χρόνον ἀντιπαραβαλλέτωσαν τοῖς πλείοσιν ἢ δισχιλίοις ἔτεσι τῆς ἡμετέρας πολιτείας,"},{"number":227,"text":"καὶ προσέτι λογιζέσθωσαν, ὅτι Λακεδαιμόνιοι ὅσον ἐφʼ ἑαυτῶν χρόνον εἶχον τὴν ἐλευθερίαν ἀκριβῶς ἔδοξαν τοὺς νόμους διαφυλάττειν, ἐπεὶ μέντοι περὶ αὐτοὺς ἐγένοντο μεταβολαὶ τῆς τύχης, μικροῦ δεῖν ἁπάντων ἐπελάθοντο τῶν νόμων."},{"number":228,"text":"ἡμεῖς δʼ ἐν τύχαις γεγονότες μυρίαις διὰ τὰς τῶν βασιλευσάντων τῆς Ἀσίας μεταβολὰς οὐδʼ ἐν τοῖς ἐσχάτοις τῶν δεινῶν τοὺς νόμους προύδομεν οὐκ ἀργίας οὐδὲ τρυφῆς αὐτοὺς χάριν περιέποντες, ἀλλʼ εἴ τις ἐθέλοι σκοπεῖν, πολλῷ τινι τῆς δοκούσης ἐπιτετάχθαι Λακεδαιμονίοις καρτερίας μείζονας ἄθλους καὶ πόνους ἡμῖν ἐπιτεθέντας *"},{"number":229,"text":"οἱ μέν γε μήτε γῆν ἐργαζόμενοι μήτε περὶ τέχνας πονοῦντες ἀλλὰ πάσης ἐργασίας ἄφετοι λιπαροὶ καὶ τὰ σώματα πρὸς κάλλος ἀσκοῦντες ἐπὶ τῆς πόλεως διῆγον,"},{"number":230,"text":"ἄλλοις ὑπηρέταις πρὸς ἅπαντα τὰ τοῦ βίου χρώμενοι καὶ τὴν τροφὴν ἑτοίμην παρʼ ἐκείνων λαμβάνοντες, ἐφ ἣν δὴ τοῦτο μόνον τὸ καλὸν ἔργον καὶ φιλάνθρωπον ἅπαντα καὶ πράττειν καὶ πάσχειν ὑπομένοντες τὸ κρατεῖν πάντων, ἐφʼ οὓς ἂν στρατεύωσιν."},{"number":231,"text":"ὅτι δὲ μηδὲ τοῦτο κατώρθωσαν, ἐῶ λέγειν· οὐ γὰρ καθʼ ἕνα μόνον, ἀλλὰ πολλοὶ πολλάκις ἀθρόως τῶν τοῦ νόμου προσταγμάτων ἀμελήσαντες αὑτοὺς μετὰ τῶν ὅπλων παρέδοσαν τοῖς πολεμίοις."},{"number":232,"text":"Ἆρʼ οὖν καὶ παρʼ ἡμῖν, οὐ λέγω τοσούτους, ἀλλὰ δύο ἢ τρεῖς ἔγνω τις προδότας γενομένους τῶν νόμων ἢ θάνατον φοβηθέντας, οὐχὶ τὸν ῥᾷστον ἐκεῖνον λέγω τὸν συμβαίνοντα τοῖς μαχομένοις, ἀλλὰ τὸν μετὰ λύμης τῶν σωμάτων, ὁποῖος εἶναι δοκεῖ πάντων χαλεπώτατος;"},{"number":233,"text":"ὃν ἔγωγε νομίζω τινὰς κρατήσαντας ἡμῶν οὐχ ὑπὸ μίσους προσφέρειν τοῖς ὑποχειρίοις, ἀλλὰ [ὡς] θαυμαστόν τι θέαμα βουλομένους ἰδεῖν, εἴ τινές εἰσιν ἄνθρωποι μόνον εἶναι κακὸν αὐτοῖς πεπιστευκότες, εἰ πρᾶξαί τι παρὰ τοὺς ἑαυτῶν νόμους εἰ λόγον εἰπεῖν παρʼ ἐκείνοις παραβιασθεῖεν."},{"number":234,"text":"οὐ χρὴ δὲ θαυμάζειν, εἰ πρὸς θάνατον ἀνδρείως ἔχομεν ὑπὲρ τῶν νόμων παρὰ τοὺς ἄλλους ἅπαντας· οὐδὲ γὰρ τὰ ῥᾷστα δοκοῦντα τῶν ἡμετέρων ἐπιτηδευμάτων ἄλλοι ῥᾳδίως ὑπομένουσιν, αὐτουργίαν λέγω καὶ τροφῆς λιτότητα καὶ τὸ μηδὲν εἰκῆ μηδʼ ὡς ἔτυχεν ἕκαστος ἐπιτεθυμηκὼς φαγεῖν ἢ πιεῖν ἢ συνουσίᾳ προσελθεῖν ἢ πολυτελείᾳ καὶ πάλιν ἀργίας ὑπομεῖναι τάξιν ἀμετακίνητον."},{"number":235,"text":"ἀλλʼ οἱ τοῖς ξίφεσιν ὁμόσε χωροῦντες καὶ τοὺς πολεμίους ἐξ ἐφόδου τρεπόμενοι τοῖς προστάγμασιν τοῖς περὶ διαίτης οὐκ ἀντέβλεψαν. ἡμῖν δὲ πάλιν ἐκ τοῦ περὶ ταῦτα τῷ νόμῳ πειθαρχεῖν ἡδέως κἀκεῖ περίεστιν ἐπιδείκνυσθαι τὸ γενναῖον."},{"number":236,"text":"Εἶτα Λυσίμαχοι καὶ Μόλωνες καὶ τοιοῦτοί τινες ἄλλοι συγγραφεῖς, ἀδόκιμοι σοφισταί, μειρακίων ἀπατεῶνες, ὡς πάνυ ἡμᾶς φαυλοτάτους ἀνθρώπων λοιδοροῦσιν."},{"number":237,"text":"ἐγὼ δʼ οὐκ ἂν ἐβουλόμην περὶ τῶν παρʼ ἑτέροις νομίμων ἐξετάζειν· τὰ γὰρ αὑτῶν ἡμῖν φυλάττειν πάτριόν ἐστιν, οὐ τῶν ἀλλοτρίων κατηγορεῖν. καὶ περί γε τοῦ μήτε χλευάζειν μήτε βλασφημεῖν τοὺς νομιζομένους θεοὺς παρʼ ἑτέροις ἄντικρυς ἡμῖν ὁ νομοθέτης ἀπείρηκεν αὐτῆς ἕνεκα προσηγορίας τοῦ θεοῦ."},{"number":238,"text":"τῶν δὲ κατηγόρων διὰ τῆς ἀντιπαραθέσεως ἡμᾶς ἐλέγχειν οἰομένων οὐχ οἷόν τε κατασιωπᾶν, ἄλλως τε καὶ τοῦ λόγου μέλλοντος οὐχ ὑφʼ ἡμῶν ἐλεγχθήσεσθαι νῦν αὐτῶν συντιθέντων, ἀλλὰ ὑπὸ πολλῶν εἰρημένου καὶ λίαν εὐδοκιμούντων."},{"number":239,"text":"τίς γὰρ τῶν παρὰ τοῖς Ἕλλησιν ἐπὶ σοφίᾳ τεθαυμασμένων οὐκ ἐπιτετίμηκεν καὶ ποιητῶν τοῖς ἐπεφανεστάτοις καὶ νομοθετῶν τοῖς μάλιστα πεπιστευμένοις, ὅτι τοιαύτας δόξας περὶ θεῶν ἐξ ἀρχῆς τοῖς πλήθεσιν ἐγκατέσπειραν,"},{"number":240,"text":"ἀριθμῷ μὲν ὁπόσους ἂν αὐτοὶ θελήσωσιν ἀποφαινόμενοι ἐξ ἀλλήλων δὲ γινομένους καὶ κατὰ παντοίους τρόπους γενέσεων, τούτους δὲ καὶ διαιροῦντες τόποις καὶ διαίταις, ὥσπερ τῶν ζῴων τὰ γένη, τοὺς μὲν ὑπὸ γῆν, τοὺς δὲ ἐν θαλάττῃ, τοὺς μέντοι πρεσβυτάτους αὐτῶν ἐν τῷ ταρτάρῳ δεδεμένους *"},{"number":241,"text":"ὅσοις δὲ τὸν οὐρανὸν ἀπένειμαν τούτοις πατέρα μὲν τῷ λόγῳ, τύραννον δὲ τοῖς ἔργοις καὶ δεσπότην ἐφιστάντες, καὶ διὰ τοῦτο συνισταμένην ἐπιβουλὴν ἐπʼ αὐτὸν ὑπὸ γυναικὸς καὶ ἀδελφοῦ καὶ θυγατρός, ἣν ἐκ τῆς ἑαυτοῦ κεφαλῆς ἐγέννησεν, ἵνα δὴ συλλαβόντες αὐτὸν καθείρξωσιν, ὥσπερ αὐτὸς ἐκεῖνος τὸν πατέρα τὸν ἑαυτοῦ."},{"number":242,"text":"Ταῦτα δικαίως μέμψεως πολλῆς ἀξιοῦσιν οἱ φρονήσει διαφέροντες καὶ πρὸς τούτοις καταγελῶσιν, εἰ τῶν θεῶν τοὺς μὲν ἀγενείους καὶ μειράκια, τοὺς δὲ πρεσβυτέρους καὶ γενειῶντας εἶναι χρὴ δοκεῖν, ἄλλους δὲ τετάχθαι πρὸς ταῖς τέχναις, χαλκεύοντά τινα, τὴν δὲ ὑφαίνουσαν, τὸν δὲ πολεμοῦντα καὶ μετὰ ἀνθρώπων μαχόμενον, τοὺς δὲ κιθαρίζοντας ἢ τοξικῇ χαίροντας,"},{"number":243,"text":"εἶτʼ αὐτοῖς ἐγγιγνομένας πρὸς ἀλλήλους στάσεις καὶ περὶ ἀνθρώπων φιλονεικίας μέχρι τοῦ μὴ μόνον ἀλλήλοις τὰς χεῖρας προσφέρειν, ἀλλὰ καὶ ὑπʼ ἀνθρώπων τραυματιζομένους ὀδύρεσθαι καὶ κακοπαθεῖν."},{"number":244,"text":"τὸ δὲ δὴ πάντων ἀσελγέστερον, τὴν περὶ τὰς μίξεις ἀκρασίαν καὶ τοὺς ἔρωτας πῶς οὐκ ἄτοπον μικροῦ δεῖν ἅπασι προσάψαι καὶ τοῖς ἄρρεσι τῶν θεῶν καὶ ταῖς θηλείαις;"},{"number":245,"text":"εἶθʼ οἱ γενναιότατοι καὶ πρῶτος αὐτὸς ὁ πατὴρ τὰς ἀπατηθείσας ὑπʼ αὐτοῦ καὶ γενομένας ἐγκύους καθειργνυμένας ἢ καταποντιζομένας περιορᾷ καὶ τοὺς ἐξ αὐτοῦ γεγονότας οὔτε σώζειν δύναται κρατούμενος ὑπὸ τῆς εἱμαρμένης οὔτʼ ἀδακρυτὶ τοὺς θανάτους αὐτῶν ὑπομένειν."},{"number":246,"text":"καλά γε ταῦτα καὶ τοῖς ἄλλοις ἑπόμενα, μοιχείας μὲν ἐν οὐρανῷ βλεπομένης οὕτως ἀναισχύντως ὑπὸ τῶν θεῶν, ὥστε τινὰς καὶ ζηλοῦν ὁμολογεῖν τοὺς ἐπʼ αὐτῇ δεδεμένους· τί γὰρ οὐκ ἔμελλον, ὁπότε μηδʼ ὁ πρεσβύτατος καὶ βασιλεὺς ἠδυνήθη τῆς πρὸς τὴν γυναῖκα μίξεως ἐπισχεῖν τὴν ὁρμὴν ὅσον γοῦν εἰς τὸ δωμάτιον ἀπελθεῖν;"},{"number":247,"text":"οἱ δὲ δὴ δουλεύοντες τοῖς ἀνθρώποις θεοὶ καὶ νῦν μὲν οἰκοδομοῦντες ἐπὶ μισθῷ νῦν δὲ ποιμαίνοντες, ἄλλοι δὲ τρόπον κακούργων ἐν χαλκῷ δεσμωτηρίῳ δεδεμένοι, τίνα τῶν εὖ φρονούντων οὐκ ἂν παροξύνειαν, ὡς τοῖς ταῦτα συνθεῖσιν ἐπιπλῆξαι καὶ πολλὴν εὐήθειαν καταγνῶναι τῶν προσεμένων;"},{"number":248,"text":"οἱ δὲ καὶ δεῖμόν τινα καὶ φόβον ἤδη δὲ καὶ λύσσαν καὶ ἀπάτην καὶ τί γὰρ οὐχὶ τῶν κακίστων παθῶν εἰς θεοῦ φύσιν καὶ μορφὴν ἀνέπλασαν· τοῖς δὲ εὐφημοτέροις τούτων καὶ θύειν τὰς πόλεις ἔπεισαν."},{"number":249,"text":"τοιγαροῦν εἰς πολλὴν ἀνάγκην καθίστανται τοὺς μέν τινας τῶν θεῶν νομίζειν δοτῆρας ἀγαθῶν, τοὺς δὲ καλεῖν ἀποτροπαίους, εἶτα δὲ τούτους ὥσπερ τοὺς πονηροτάτους τῶν ἀνθρώπων χάρισι καὶ δώροις ἀποσείονται, μέγα τι λήψεσθαι κακὸν ὑπʼ αὐτῶν προσδοκῶντες, εἰ μὴ μισθὸν αὐτοῖς παράσχοιεν."},{"number":250,"text":"Τί τοίνυν τὸ αἴτιον τῆς τοσαύτης ἀνωμαλίας καὶ περὶ τὸ θεῖον πλημμελείας; ἐγὼ μὲν ὑπολαμβάνω τὸ μήτε τὴν ἀληθῆ τοῦ θεοῦ φύσιν ἐξ ἀρχῆς συνιδεῖν αὐτῶν τοὺς νομοθέτας μήθʼ ὅσον καὶ λαβεῖν ἠδυνήθησαν ἀκριβῆ γνῶσιν διορίσαντας πρὸς τοῦτο ποιήσασθαι τὴν ἄλλην τάξιν τοῦ πολιτεύματος,"},{"number":251,"text":"ἀλλʼ ὥσπερ ἄλλο τι τῶν φαυλοτάτων ἐφῆκαν τοῖς μὲν ποιηταῖς οὕστινας ἂν βούλωνται θεοὺς εἰσάγειν πάντα πάσχοντας, τοῖς δὲ ῥήτορσι πολιτογραφεῖν κατὰ ψήφισμα τῶν ξένων θεῶν τὸν ἐπιτήδειον·"},{"number":252,"text":"πολλῆς δὲ καὶ ζωγράφοι καὶ πλάσται τῆς εἰς τοῦτο παρὰ τῶν Ἑλλήνων ἀπέλαυσαν ἐξουσίας, αὐτὸς ἕκαστός τινα μορφὴν ἐπινοῶν, ὁ μὲν ἐκ πηλοῦ πλάττων, ὁ δὲ γράφων, οἱ δὲ μάλιστα δὴ θαυμαζόμενοι τῶν δημιουργῶν τὸν ἐλέφαντα καὶ τὸν χρυσὸν ἔχουσι τῆς ἀεὶ καινουργίας τὴν ὑπόθεσιν."},{"number":253,"text":"[καὶ τὰ μὲν τῶν ἱερῶν ἐν ἐρημίᾳ παντελῶς εἰσιν, τὰ δὲ ἐμπερισπούδαστα καθάρσεσι παντοδαπαῖς περικοσμούμενα.] εἶθʼ οἱ μὲν πρότερον ἐν ταῖς τιμαῖς ἀκμάσαντες θεοὶ γεγηράκασιν· [οἱ δὲ ὑπακμάζοντες τούτων ἐν δευτέρᾳ τάξει ὑποβέβληνται] οὕτω γὰρ εὐφημότερον λέγειν·"},{"number":254,"text":"ἄλλοι δὲ καινοί τινες εἰσαγόμενοι θρησκείας τυγχάνουσιν, [ὡς ἐν παρεκβάσει ὧν προείπομεν τοὺς τόπους ἐρημωθέντας καταλιπεῖν] καὶ τῶν ἱερῶν τὰ μὲν ἐρημοῦται, τὰ δὲ νεωστὶ κατὰ τὴν αὐτῶν βούλησιν ἕκαστος ἱδρύεται, δέον [τοίνυν] τοὐναντίον τὴν περὶ τοῦ θεοῦ δόξαν αὐτοὺς καὶ τὴν πρὸς αὐτὸν τιμὴν ἀμετακίνητον διαφυλάττειν."},{"number":255,"text":"Ἀπολλώνιος μὲν οὖν ὁ Μόλων τῶν ἀνοήτων εἷς ἦν καὶ τετυφωμένων, τοὺς μέντοι κατʼ ἀλήθειαν ἐν τοῖς Ἑλληνικοῖς φιλοσοφήσαντας οὔτε τῶν προειρημένων οὐδὲν διέλαθεν οὔτε τὰς ψυχρὰς προφάσεις τῶν ἀλληγοριῶν ἠγνόησαν, διόπερ τῶν μὲν εἰκότως κατεφρόνησαν, εἰς δὲ τὴν ἀληθῆ καὶ πρέπουσαν περὶ τοῦ θεοῦ δόξαν ἡμῖν συνεφώνησαν."},{"number":256,"text":"ἀφʼ ἧς ὁρμηθεὶς ὁ Πλάτων οὔτε τῶν ἄλλων οὐδένα ποιητῶν φησι δεῖν εἰς τὴν πολιτείαν παραδέχεσθαι καὶ τὸν Ὅμηρον εὐφήμως ἀποπέμπεται στεφανώσας καὶ μύρον αὐτοῦ καταχέας, ἵνα δὴ μὴ τὴν ὀρθὴν δόξαν περὶ θεοῦ τοῖς μύθοις ἀφανίσειε."},{"number":257,"text":"μάλιστα δὲ Πλάτων μεμίμηται τὸν ἡμέτερον νομοθέτην κἀν τῷ μηδὲν οὕτω παίδευμα προστάττειν τοῖς πολίταις ὡς τὸ πάντας ἀκριβῶς τοὺς νόμους ἐκμανθάνειν, καὶ μὴν καὶ περὶ τοῦ μὴ δεῖν ὡς ἔτυχεν ἐπιμίγνυσθαί τινας ἔξωθεν, ἀλλʼ εἶναι καθαρὸν"},{"number":258,"text":"τὸ πολίτευμα τῶν ἐμμενόντων τοῖς νόμοις προυνόησεν. ὧν οὐδὲν λογισάμενος ὁ Μόλων Ἀπολλώνιος ἡμῶν κατηγόρησεν, ὅτι μὴ παραδεχόμεθα τοὺς ἄλλαις προκατειλημμένους δόξαις περὶ θεοῦ μηδὲ κοινωνεῖν ἐθέλομεν τοῖς καθʼ ἑτέραν συνήθειαν βίου ζῆν προαιρουμένοις."},{"number":259,"text":"ἀλλʼ οὐδὲ τοῦτʼ ἔστιν ἴδιον ἡμῶν, κοινὸν δὲ πάντων, οὐχ Ἑλλήνων δὲ μόνων, ἀλλὰ καὶ τῶν ἐν τοῖς Ἕλλησιν εὐδοκιμωτάτων· Λακεδαιμόνιοι δὲ καὶ ξενηλασίας ποιούμενοι διετέλουν καὶ τοῖς αὐτῶν ἀποδημεῖν πολίταις οὐκ ἐπέτρεπον διαφθορὰν ἐξ ἀμφοῖν ὑφορώμενοι γενήσεσθαι περὶ τοὺς νόμους."},{"number":260,"text":"ἐκείνοις μὲν οὖν τάχʼ ἂν δυσκολίαν τις ὀνειδίσειεν εἰκότως· οὐδενὶ γὰρ οὔτε τῆς πολιτείας οὔτε τῆς παρʼ αὐτοῖς μετεδίδοσαν διατριβῆς·"},{"number":261,"text":"ἡμεῖς δὲ τὰ μὲν τῶν ἄλλων ζηλοῦν οὐκ ἀξιοῦμεν, τοὺς μέντοι μετέχειν τῶν ἡμετέρων βουλομένους ἡδέως δεχόμεθα. καὶ τοῦτο ἂν εἴη τεκμήριον, οἶμαι, φιλανθρωπίας ἅμα καὶ μεγαλοψυχίας."},{"number":262,"text":"Ἐῶ περὶ Λακεδαιμονίων ἐπὶ πλείω λέγειν. οἱ δὲ κοινὴν εἶναι τὴν ἑαυτῶν δόξαντες πόλιν Ἀθηναῖοι πῶς περὶ τούτων εἶχον, Ἀπολλώνιος ἠγνόησεν, ὅτι καὶ τοὺς ῥῆμα μόνον παρὰ τοὺς ἐκείνων νόμους φθεγξαμένους περὶ θεῶν ἀπαραιτήτως ἐκόλασαν."},{"number":263,"text":"τίνος γὰρ ἑτέρου χάριν Σωκράτης ἀπέθανεν; οὐ γὰρ δὴ προεδίδου τὴν πόλιν τοῖς πολεμίοις οὐδὲ τῶν ἱερῶν ἐσύλησεν οὐδέν, ἀλλʼ ὅτι καινοὺς ὅρκους ὤμνυεν καί τι δαιμόνιον αὐτῷ σημαίνειν ἔφασκεν ἢ διαπαίζων, ὡς ἔνιοι λέγουσι, διὰ ταῦτα κατεγνώσθη κώνειον πιὼν ἀποθανεῖν."},{"number":264,"text":"καὶ διαφθείρειν δὲ τοὺς νέους ὁ κατήγορος αὐτὸν ᾐτιᾶτο, τῆς πατρίου πολιτείας καὶ τῶν νόμων ὅτι προῆγεν αὐτοὺς καταφρονεῖν. Σωκράτης μὲν οὖν πολίτης Ἀθηναίων τοιαύτην ὑπέμεινε τιμωρίαν."},{"number":265,"text":"Ἀναξαγόρας δὲ Κλαζομένιος ἦν, ἀλλʼ ὅτι νομιζόντων Ἀθηναίων τὸν ἥλιον εἶναι θεὸν ὅδʼ αὐτὸν ἔφη μύδρον εἶναι διάπυρον, θάνατον αὐτοῦ παρʼ ὀλίγας ψήφους κατέγνωσαν."},{"number":266,"text":"καὶ Διαγόρᾳ τῷ Μηλίῳ τάλαντον ἐπεκήρυξαν, εἴ τις αὐτὸν ἀνέλοι, ἐπεὶ τὰ παρʼ αὐτοῖς μυστήρια χλευάζειν ἐλέγετο. καὶ Πρωταγόρας εἰ μὴ θᾶττον ἔφυγε, συλληφθεὶς ἂν ἐτεθνήκει γράψαι τι δόξας οὐχ ὁμολογούμενον τοῖς Ἀθηναίοις περὶ θεῶν."},{"number":267,"text":"τί δὲ δεῖ θαυμάζειν, εἰ πρὸς ἄνδρας οὕτως ἀξιοπίστους διετέθησαν, οἵ γε μηδὲ γυναικῶν ἐφείσαντο; νῦν γὰρ τὴν ἱέρειαν ἀπέκτειναν, ἐπεί τις αὐτῆς κατηγόρησεν, ὅτι ξένους ἐμύει θεούς· νόμῳ δʼ ἦν τοῦτο παρʼ αὐτοῖς κεκωλυμένον καὶ τιμωρία κατὰ τῶν ξένον εἰσαγόντων θεὸν ὥριστο θάνατος."},{"number":268,"text":"οἱ δὲ τοιούτῳ νόμῳ χρώμενοι δῆλον ὅτι τοὺς τῶν ἄλλων οὐκ ἐνόμιζον εἶναι θεούς· οὐ γὰρ ἂν αὐτοῖς πλειόνων ἀπολαύειν ἐφθόνουν."},{"number":269,"text":"τὰ μὲν οὖν Ἀθηναίων ἐχέτω καλῶς. Σκύθαι δὲ φόνοις χαίροντες ἀνθρώπων καὶ βραχὺ τῶν θηρίων διαφέροντες, ὅμως τὰ παρʼ αὐτοῖς οἴονται δεῖν περιστέλλειν, καὶ τὸν ὑπὸ τῶν Ἑλλήνων ἐπὶ σοφίᾳ θαυμασθέντα τὸν Ἀνάχαρσιν ἐπανελθόντα πρὸς αὐτοὺς ἀνεῖλον, ἐπεὶ τῶν Ἑλληνικῶν ἐθῶν ἔδοξεν ἥκειν ἀνάπλεως, πολλοὺς δὲ καὶ παρὰ Πέρσαις ἄν τις εὕροι καὶ διὰ τὴν αὐτὴν αἰτίαν κεκολασμένους."},{"number":270,"text":"ἀλλὰ δῆλον ὅτι τοῖς Περσῶν ἔχαιρε νόμοις ὁ Ἀπολλώνιος κἀκείνους ἐθαύμαζεν, ὅτι τῆς ἀνδρείας αὐτῶν ἀπέλαυσαν οἱ Ἕλληνες καὶ τῆς ὁμογνωμοσύνης ἧς εἶχον περὶ θεῶν, ταύτης μὲν [οὖν] ἐν τοῖς ἱεροῖς οἷς κατέπρησαν, τῆς ἀνδρείας δὲ δουλεῦσαι παρὰ μικρὸν ἐλθόντες, ἁπάντων δὲ καὶ τῶν ἐπιτηδευμάτων μιμητὴς ἐγένετο τῶν Περσικῶν γυναῖκας ἀλλοτρίας ὑβρίζων καὶ παῖδας ἐκτέμνων."},{"number":271,"text":"παρʼ ἡμῖν δὲ θάνατος ὥρισται, κἂν ἄλογόν τις οὕτω ζῷον ἀδικῇ· καὶ τούτων ἡμᾶς τῶν νόμων ἀπαγαγεῖν οὔτε φόβος ἴσχυσεν τῶν κρατησάντων οὔτε ζῆλος τῶν παρὰ τοῖς ἄλλοις τετιμημένων."},{"number":272,"text":"οὐδὲ τὴν ἀνδρείαν ἠσκήσαμεν ἐπὶ τῷ πολέμους ἄρασθαι χάριν πλεονεξίας, ἀλλʼ ἐπὶ τῷ τοὺς νόμους διαφυλάττειν. τὰς γοῦν ἄλλας ἐλαττώσεις πρᾴως ὑπομένοντες, ἐπειδάν τινες ἡμᾶς τὰ νόμιμα κινεῖν ἀναγκάζωσι, τότε καὶ παρὰ δύναμιν αἱρούμεθα πολέμους καὶ μέχρι τῶν ἐσχάτων ταῖς συμφοραῖς ἐγκαρτεροῦμεν."},{"number":273,"text":"διὰ τί γὰρ ἂν καὶ ζηλώσαιμεν τοὺς ἑτέρων νόμους ὁρῶντες μηδὲ παρὰ τοῖς θεμένοις αὐτοὺς τετηρημένους; πῶς γὰρ οὐκ ἔμελλον Λακεδαιμόνιοι μὲν τῆς ἀνεπιμίκτου καταγνώσεσθαι πολιτείας καὶ τῆς περὶ τοὺς γάμους ὀλιγωρίας, Ἠλεῖοι δὲ καὶ Θηβαῖοι τῆς παρὰ φύσιν καὶ [ἄγαν] ἀνέδην πρὸς τοὺς ἄρρενας μίξεως;"},{"number":274,"text":"ἃ γοῦν πάλαι κάλλιστα καὶ συμφορώτατα πράττειν ὑπελάμβανον, ταῦτʼ εἰ καὶ μὴ παντάπασι τοῖς ἔργοις πεφεύγασιν, οὐχ ὁμολογοῦσιν,"},{"number":275,"text":"ἀλλὰ καὶ τοὺς περὶ αὐτῶν νόμους ἀπόμνυνται τοσοῦτόν ποτε παρὰ τοῖς Ἕλλησιν ἰσχύσαντας, ὥστε καὶ τοῖς θεοῖς τὰς τῶν ἀρρένων μίξεις ἐπεφήμισαν, κατὰ τὸν αὐτὸν δὲ λόγον καὶ τοὺς τῶν γνησίων ἀδελφῶν γάμους, ταύτην ἀπολογίαν αὑτοῖς τῶν ἀτόπων καὶ παρὰ φύσιν ἡδονῶν συντιθέντες."},{"number":276,"text":"Ἐῶ νῦν περὶ τῶν τιμωριῶν λέγειν, ὅσας μὲν ἐξ ἀρχῆς ἔδοσαν οἱ πλεῖστοι νομοθέται τοῖς πονηροῖς διαλύσεις, ἐπὶ μοιχείας μὲν ζημίας χρημάτων, ἐπὶ φθορᾶς δὲ καὶ γάμους νομοθετήσαντες, ὅσας δὲ περὶ τῆς ἀσεβείας προφάσεις περιέχουσιν ἀρνήσεως, εἰ καί τις ἐπιχειρήσειεν ἐξετάζειν· ἤδη γὰρ παρὰ τοῖς πλείοσι μελέτη"},{"number":277,"text":"γέγονε τοῦ παραβαίνειν τοὺς νόμους. οὐ μὴν καὶ παρʼ ἡμῖν, ἀλλὰ κἂν πλούτου καὶ πόλεων καὶ τῶν ἄλλων ἀγαθῶν στερηθῶμεν, ὁ γοῦν νόμος ἡμῖν ἀθάνατος διαμένει, καὶ οὐδεὶς Ἰουδαίων οὔτε μακρὰν οὕτως ἂν ἀπέλθοι τῆς πατρίδος οὔτε πικρὸν φοβηθήσεται"},{"number":278,"text":"δεσπότην, ὡς μὴ πρὸ ἐκείνου δεδιέναι τὸν νόμον. εἰ μὲν οὖν διὰ τὴν ἀρετὴν τῶν νόμων οὕτως πρὸς αὐτοὺς διακείμεθα, συγχωρησάτωσαν ὅτι κρατίστους ἔχομεν νόμους. εἰ δὲ φαύλοις οὕτως ἡμᾶς ἐμμένειν ὑπολαμβάνουσι, τί οὐκ ἂν αὐτοὶ δικαίως πάθοιεν τοὺς κρείττονας οὐ φυλάττοντες;"},{"number":279,"text":"ἐπεὶ τοίνυν ὁ πολὺς χρόνος πιστεύεται πάντων εἶναι δοκιμαστὴς ἀληθέστατος, τοῦτον ἂν ποιησαίμην ἐγὼ μάρτυρα τῆς ἀρετῆς ἡμῶν τοῦ νομοθέτου καὶ τῆς ὑπʼ ἐκείνου φήμης περὶ τοῦ θεοῦ παραδοθείσης· ἀπείρου γὰρ τοῦ χρόνου γεγονότος, εἴ τις αὐτὸν παραβάλλοι ταῖς τῶν ἄλλων ἡλικίαις νομοθετῶν, παρὰ πάντας εὕροι τοῦτον,"},{"number":280,"text":"ὑφʼ ἡμῶν τε διηλέγχθησαν οἱ νόμοι καὶ τοῖς ἄλλοις ἅπασιν ἀνθρώποις ἀεὶ καὶ μᾶλλον αὑτῶν ζῆλον ἐμπεποιήκασι."},{"number":281,"text":"πρῶτοι μὲν γὰρ οἱ παρὰ τοῖς Ἕλλησι φιλοσοφήσαντες τῷ μὲν δοκεῖν τὰ πάτρια διεφύλαττον, ἐν δὲ τοῖς πράγμασι καὶ τῷ φιλοσοφεῖν ἐκείνῳ κατηκολούθησαν, ὅμοια μὲν περὶ θεοῦ φρονοῦντες, εὐτέλειαν δὲ βίου καὶ τὴν πρὸς ἀλλήλους κοινωνίαν διδάσκοντες."},{"number":282,"text":"οὐ μὴν ἀλλὰ καὶ πλήθεσιν ἤδη πολὺς ζῆλος γέγονεν ἐκ μακροῦ τῆς ἡμετέρας εὐσεβείας, οὐδʼ ἔστιν οὐ πόλις Ἑλλήνων οὐδητισοῦν οὐδὲ βάρβαρον οὐδὲ ἓν ἔθνος, ἔνθα μὴ τὸ τῆς ἑβδομάδος, ἣν ἀργοῦμεν ἡμεῖς, τὸ ἔθος [δὲ] διαπεφοίτηκεν καὶ αἱ νηστεῖαι καὶ λύχνων ἀνακαύσεις καὶ πολλὰ τῶν εἰς βρῶσιν ἡμῖν οὐ νενομισμένων παρατετήρηται."},{"number":283,"text":"μιμεῖσθαι δὲ πειρῶνται καὶ τὴν πρὸς ἀλλήλους ἡμῶν ὁμόνοιαν καὶ τὴν τῶν ὄντων ἀνάδοσιν καὶ τὸ φιλεργὸν ἐν ταῖς τέχναις καὶ τὸ καρτερικὸν ἐν ταῖς ὑπὲρ τῶν νόμων ἀνάγκαις·"},{"number":284,"text":"τὸ γὰρ θαυμασιώτατον, ὅτι χωρὶς τοῦ τῆς ἡδονῆς ἐπαγωγοῦ δελέατος αὐτὸς καθʼ ἑαυτὸν ἴσχυσεν ὁ νόμος, καὶ ὥσπερ ὁ θεὸς διὰ παντὸς τοῦ κόσμου πεφοίτηκεν, οὕτως ὁ νόμος διὰ πάντων ἀνθρώπων βεβάδικεν. αὐτὸς δέ τις ἕκαστος τὴν πατρίδα καὶ τὸν οἶκον ἐπισκοπῶν τὸν αὐτοῦ τοῖς ὑπʼ ἐμοῦ λεγομένοις οὐκ ἀπιστήσει."},{"number":285,"text":"χρὴ τοίνυν πάντων ἀνθρώπων καταγνῶναι πονηρίαν ἐθελούσιον, εἰ τἀλλότρια καὶ φαῦλα πρὸ τῶν οἰκείων καὶ καλῶν ζηλοῦν ἐπιτεθυμήκασιν, ἢ παύσασθαι βασκαίνοντας ἡμῖν τοὺς κατηγοροῦντας."},{"number":286,"text":"οὐδὲ γὰρ ἐπιφθόνου τινὸς ἀντιποιούμεθα πράγματος τὸν αὑτῶν τιμῶντες νομοθέτην καὶ τοῖς ὑπʼ ἐκείνου προφητευθεῖσι περὶ τοῦ θεοῦ πεπιστευκότες· καὶ γὰρ εἰ μὴ συνίεμεν αὐτοὶ τῆς ἀρετῆς τῶν νόμων, ἁπάντων ἂν ὑπὸ τοῦ πλήθους τῶν ζηλούντων μέγα φρονεῖν ἐπʼ αὐτοῖς προήχθημεν."},{"number":287,"text":"Ἀλλὰ γὰρ περὶ μὲν τῶν νόμων καὶ τῆς πολιτείας τὴν ἀκριβῆ πεποίημαι παράδοσιν ἐν τοῖς περὶ ἀρχαιολογίας μοι γραφεῖσι. νυνὶ δʼ αὐτῶν ἐπεμνήσθην ἐφʼ ὅσον ἦν ἀναγκαῖον, οὔτε τὰ τῶν ἄλλων ψέγειν οὔτε τὰ παρʼ ἡμῖν ἐγκωμιάζειν προθέμενος, ἀλλʼ ἵνα τοὺς περὶ ἡμῶν ἀδίκως γεγραφότας ἐλέγξω πρὸς αὐτὴν ἀναιδῶς τὴν ἀλήθειαν πεφιλονεικηκότας."},{"number":288,"text":"καὶ δή μοι δοκῶ πεπληρῶσθαι διὰ τῆς γραφῆς ἱκανῶς ἃ προϋπεσχόμην· καὶ γὰρ ἀρχαιότητι προϋπάρχον ἐπέδειξα τὸ γένος, τῶν κατηγόρων ὅτι νεώτατόν ἐστιν εἰρηκότων, [καὶ γὰρ] καὶ πολλοὺς ἐν τοῖς συγγράμμασιν ἐμνημονευκότας ἡμῶν ἀρχαίους παρέσχομεν μάρτυρας, ἐκείνων ὅτι μηδείς ἐστιν διαβεβαιουμένων."},{"number":289,"text":"ἀλλὰ μὴν Αἰγυπτίους ἔφασαν ἡμῶν τοὺς προγόνους· ἐδείχθησαν δʼ εἰς Αἴγυπτον ἐλθόντες ἑτέρωθεν. διὰ δὲ λύμην σωμάτων αὐτοὺς ἐκβληθῆναι κατεψεύσαντο· προαιρέσει καὶ περιουσίᾳ ῥώμης ἐφάνησαν ἐπὶ τὴν οἰκείαν ὑποστρέψαντες γῆν."},{"number":290,"text":"οἱ μὲν ὡς φαυλότατον ἡμῶν τὸν νομοθέτην ἐλοιδόρησαν· τῷ δὲ τῆς ἀρετῆς πάλαι μὲν ὁ θεός, μετʼ ἐκεῖνον δὲ μάρτυς ὁ χρόνος εὕρηται γεγενημένος."},{"number":291,"text":"Περὶ τῶν νόμων οὐκ ἐδέησε λόγου πλείονος· αὐτοὶ γὰρ ἑωράθησαν διʼ αὐτῶν οὐκ ἀσέβειαν μὲν εὐσέβειαν δʼ ἀληθεστάτην διδάσκοντες, οὐδʼ ἐπὶ μισανθρωπίαν, ἀλλʼ ἐπὶ τὴν τῶν ὄντων κοινωνίαν παρακαλοῦντες, ἀδικίας ἐχθροί, δικαιοσύνης ἐπιμελεῖς, ἀργίαν καὶ πολυτέλειαν ἐξορίζοντες, αὐτάρκεις καὶ φιλοπόνους εἶναι διδάσκοντες, πολέμων μὲν ἀπείργοντες εἰς πλεονεξίαν,"},{"number":292,"text":"ἀνδρείους δὲ ὑπὲρ αὑτῶν εἶναι παρασκευάζοντες, ἀπαραίτητοι πρὸς τὰς τιμωρίας, ἀσόφιστοι λόγων παρασκευαῖς, τοῖς ἔργοις ἀεὶ βεβαιούμενοι· ταῦτα γὰρ [ἀεὶ] ἡμεῖς παρέχομεν τῶν γραμμάτων ἐναργέστερα."},{"number":293,"text":"διόπερ ἐγὼ θαρσήσας ἂν εἴποιμι πλείστων ἅμα καὶ καλλίστων ἡμᾶς εἰσηγητὰς τοῖς ἄλλοις γεγονέναι· τί γὰρ εὐσεβείας ἀπαραβάτου κάλλιον; τί δὲ τοῦ πειθαρχεῖν τοῖς νόμοις δικαιότερον;"},{"number":294,"text":"ἢ τί συμφορώτερον τοῦ πρὸς ἀλλήλους ὁμονοεῖν καὶ μήτʼ ἐν συμφοραῖς διίστασθαι μήτʼ ἐν εὐτυχίαις στασιάζειν ἐξυβρίζοντας, ἀλλʼ ἐν πολέμῳ μὲν θανάτου καταφρονεῖν, ἐν εἰρήνῃ δὲ τέχναις ἢ γεωργίαις προσανέχειν, πάντα δὲ καὶ πανταχοῦ πεπεῖσθαι τὸν θεὸν ἐποπτεύοντα διέπειν;"},{"number":295,"text":"ταῦτʼ εἰ μὲν παρʼ ἑτέροις ἢ ἐγράφη πρότερον ἢ ἐφυλάχθη βεβαιότερον, ἡμεῖς ἂν ἐκείνοις χάριν ὠφείλομεν ὡς μαθηταὶ γεγονότες· εἰ δὲ καὶ χρώμενοι μάλιστα πάντων βλεπόμεθα καὶ τὴν πρώτην εὕρεσιν αὐτῶν ἡμετέραν οὖσαν ἐπεδείξαμεν, Ἀπίωνες μὲν καὶ Μόλωνες καὶ πάντες ὅσοι τῷ ψεύδεσθαι καὶ λοιδορεῖν χαίρουσιν ἐξεληλέγχθωσαν."},{"number":296,"text":"σοὶ δέ, Ἐπαφρόδιτε, μάλιστα τὴν ἀλήθειαν ἀγαπῶντι καὶ διὰ σὲ τοῖς ὁμοίως βουλησομένοις περὶ τοῦ γένους ἡμῶν εἰδέναι τοῦτο καὶ τὸ πρὸ αὐτοῦ γεγράφθω βιβλίον."}]},"count":296,"chapterMarkers":false};})();